        app.button_map
            .record_button(TuiButton::BrowseList, Rect::new(2, 2, 40, 12));
        app.button_map
            .record_button(TuiButton::BrowseEntry(0), Rect::new(2, 3, 40, 1));

        open_context_menu(&mut app, 5, 10);

