#[cfg(target_os = "linux")]
#[derive(Debug, Clone)]
struct LinuxFileTaskMountInfo {
    mount_root: std::path::PathBuf,
    mount_point: std::path::PathBuf,
    filesystem_type: String,
    source: String,
}

#[cfg(target_os = "linux")]
fn unescape_linux_mountinfo_bytes(value: &str) -> Vec<u8> {
    let bytes = value.as_bytes();
    let mut output = Vec::with_capacity(bytes.len());
    let mut index = 0usize;
    while index < bytes.len() {
        if bytes[index] == b'\\' && index + 3 < bytes.len() {
            let octal = &bytes[index + 1..index + 4];
            if octal.iter().all(|byte| matches!(byte, b'0'..=b'7')) {
                let decoded = u16::from(octal[0] - b'0') * 64
                    + u16::from(octal[1] - b'0') * 8
                    + u16::from(octal[2] - b'0');
                if let Ok(decoded) = u8::try_from(decoded) {
                    output.push(decoded);
                    index += 4;
                    continue;
                }
            }
        }
        output.push(bytes[index]);
        index += 1;
    }
    output
}

#[cfg(target_os = "linux")]
fn linux_mountinfo_path(value: &str) -> std::path::PathBuf {
    use std::os::unix::ffi::OsStringExt;
    std::path::PathBuf::from(std::ffi::OsString::from_vec(
        unescape_linux_mountinfo_bytes(value),
    ))
}

#[cfg(target_os = "linux")]
fn linux_mountinfo_string(value: &str) -> String {
    String::from_utf8_lossy(&unescape_linux_mountinfo_bytes(value)).into_owned()
}

#[cfg(target_os = "linux")]
fn linux_file_task_mount_info(
    resolved_anchor: &std::path::Path,
) -> Result<LinuxFileTaskMountInfo, String> {
    let mountinfo = std::fs::read_to_string("/proc/self/mountinfo")
        .map_err(|error| format!("read /proc/self/mountinfo: {error}"))?;
    let mut best: Option<LinuxFileTaskMountInfo> = None;
    for line in mountinfo.lines() {
        let Some((left, right)) = line.split_once(" - ") else {
            continue;
        };
        let left_fields = left.split_whitespace().collect::<Vec<_>>();
        let right_fields = right.split_whitespace().collect::<Vec<_>>();
        if left_fields.len() < 5 || right_fields.len() < 2 {
            continue;
        }
        let mount_point = linux_mountinfo_path(left_fields[4]);
        if !resolved_anchor.starts_with(&mount_point) {
            continue;
        }
        let candidate = LinuxFileTaskMountInfo {
            mount_root: linux_mountinfo_path(left_fields[3]),
            mount_point,
            filesystem_type: right_fields[0].to_string(),
            source: linux_mountinfo_string(right_fields[1]),
        };
        if best.as_ref().map_or(true, |current| {
            candidate.mount_point.as_os_str().len() > current.mount_point.as_os_str().len()
        }) {
            best = Some(candidate);
        }
    }
    best.ok_or_else(|| {
        format!(
            "no active mount boundary contains endpoint anchor {}",
            resolved_anchor.display()
        )
    })
}

#[cfg(target_os = "linux")]
fn linux_filesystem_uuid_for_source(source: &str) -> Option<String> {
    if let Some(uuid) = source.strip_prefix("UUID=").filter(|uuid| !uuid.is_empty()) {
        return Some(uuid.to_ascii_lowercase());
    }
    let source_path = std::path::Path::new(source);
    if source_path.starts_with("/dev/disk/by-uuid") {
        return source_path
            .file_name()
            .map(|name| name.to_string_lossy().to_ascii_lowercase());
    }
    if !source_path.is_absolute() || !source_path.starts_with("/dev") {
        return None;
    }
    let canonical_source = std::fs::canonicalize(source_path).ok()?;
    let entries = std::fs::read_dir("/dev/disk/by-uuid").ok()?;
    for entry in entries.flatten() {
        let path = entry.path();
        if std::fs::canonicalize(&path).ok().as_deref() == Some(canonical_source.as_path()) {
            return path
                .file_name()
                .map(|name| name.to_string_lossy().to_ascii_lowercase());
        }
    }
    None
}

#[cfg(target_os = "linux")]
fn linux_mount_source_is_reattachment_stable(filesystem_type: &str, source: &str) -> bool {
    match filesystem_type {
        "sshfs" | "fuse.sshfs" => source.contains(':') && source != "sshfs",
        "nfs" | "nfs4" | "ceph" => source.contains(":/"),
        "cifs" | "smb3" => source.starts_with("//"),
        "9p" | "afs" | "coda" => {
            !source.is_empty() && source != "none" && source != filesystem_type
        }
        _ => false,
    }
}

#[cfg(target_os = "linux")]
fn linux_stable_endpoint_identity(
    mount: &LinuxFileTaskMountInfo,
) -> Option<super::file_task_runtime::DurableUnixEndpointStableIdentity> {
    if let Some(uuid) = linux_filesystem_uuid_for_source(&mount.source) {
        return Some(
            super::file_task_runtime::DurableUnixEndpointStableIdentity::FilesystemUuid {
                uuid,
                filesystem_type: mount.filesystem_type.clone(),
                mount_root: mount.mount_root.clone(),
            },
        );
    }
    linux_mount_source_is_reattachment_stable(&mount.filesystem_type, &mount.source).then(|| {
        super::file_task_runtime::DurableUnixEndpointStableIdentity::MountSource {
            source: mount.source.clone(),
            filesystem_type: mount.filesystem_type.clone(),
            mount_root: mount.mount_root.clone(),
        }
    })
}

#[cfg(target_os = "macos")]
#[derive(Debug, Clone)]
struct MacOsFileTaskMountInfo {
    mount_point: std::path::PathBuf,
    filesystem_type: String,
    volume_uuid: Option<String>,
}

#[cfg(target_os = "macos")]
#[repr(C)]
struct MacOsAttrList {
    bitmapcount: u16,
    reserved: u16,
    commonattr: u32,
    volattr: u32,
    dirattr: u32,
    fileattr: u32,
    forkattr: u32,
}

#[cfg(target_os = "macos")]
#[repr(C)]
struct MacOsVolumeUuidReply {
    length: u32,
    uuid: [u8; 16],
}

#[cfg(target_os = "macos")]
fn macos_volume_uuid(mount_point: &std::path::Path) -> Result<String, String> {
    use std::os::unix::ffi::OsStrExt;

    let path = std::ffi::CString::new(mount_point.as_os_str().as_bytes()).map_err(|_| {
        format!(
            "macOS volume mount point contains an interior NUL byte: {}",
            mount_point.display()
        )
    })?;
    let mut attributes = MacOsAttrList {
        bitmapcount: libc::ATTR_BIT_MAP_COUNT,
        reserved: 0,
        commonattr: 0,
        volattr: libc::ATTR_VOL_INFO | libc::ATTR_VOL_UUID,
        dirattr: 0,
        fileattr: 0,
        forkattr: 0,
    };
    let mut reply = MacOsVolumeUuidReply {
        length: 0,
        uuid: [0; 16],
    };
    let result = unsafe {
        libc::getattrlist(
            path.as_ptr(),
            (&mut attributes as *mut MacOsAttrList).cast::<libc::c_void>(),
            (&mut reply as *mut MacOsVolumeUuidReply).cast::<libc::c_void>(),
            std::mem::size_of::<MacOsVolumeUuidReply>(),
            0,
        )
    };
    if result != 0 {
        return Err(format!(
            "read persistent macOS volume UUID for {}: {}",
            mount_point.display(),
            std::io::Error::last_os_error()
        ));
    }
    if (reply.length as usize) < std::mem::size_of::<MacOsVolumeUuidReply>() {
        return Err(format!(
            "macOS returned a truncated volume UUID attribute for {}",
            mount_point.display()
        ));
    }
    if reply.uuid.iter().all(|byte| *byte == 0) {
        return Err(format!(
            "macOS returned an empty volume UUID for {}",
            mount_point.display()
        ));
    }
    let bytes = reply.uuid;
    Ok(format!(
        "{:02x}{:02x}{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}-{:02x}{:02x}{:02x}{:02x}{:02x}{:02x}",
        bytes[0],
        bytes[1],
        bytes[2],
        bytes[3],
        bytes[4],
        bytes[5],
        bytes[6],
        bytes[7],
        bytes[8],
        bytes[9],
        bytes[10],
        bytes[11],
        bytes[12],
        bytes[13],
        bytes[14],
        bytes[15],
    ))
}

#[cfg(target_os = "macos")]
fn macos_file_task_mount_info(
    resolved_anchor: &std::path::Path,
) -> Result<MacOsFileTaskMountInfo, String> {
    use std::os::unix::ffi::{OsStrExt, OsStringExt};

    let path = std::ffi::CString::new(resolved_anchor.as_os_str().as_bytes()).map_err(|_| {
        format!(
            "macOS endpoint anchor contains an interior NUL byte: {}",
            resolved_anchor.display()
        )
    })?;
    let mut stat = std::mem::MaybeUninit::<libc::statfs>::zeroed();
    if unsafe { libc::statfs(path.as_ptr(), stat.as_mut_ptr()) } != 0 {
        return Err(format!(
            "inspect macOS mount containing endpoint anchor {}: {}",
            resolved_anchor.display(),
            std::io::Error::last_os_error()
        ));
    }
    let stat = unsafe { stat.assume_init() };
    let c_char_bytes = |value: &[libc::c_char]| {
        let end = value
            .iter()
            .position(|byte| *byte == 0)
            .unwrap_or(value.len());
        value[..end]
            .iter()
            .map(|byte| *byte as u8)
            .collect::<Vec<_>>()
    };
    let mount_point_bytes = c_char_bytes(&stat.f_mntonname);
    let filesystem_type =
        String::from_utf8_lossy(&c_char_bytes(&stat.f_fstypename)).into_owned();
    let mount_point = std::path::PathBuf::from(std::ffi::OsString::from_vec(
        mount_point_bytes,
    ));
    let volume_uuid = macos_volume_uuid(&mount_point).ok();
    Ok(MacOsFileTaskMountInfo {
        mount_point,
        filesystem_type,
        volume_uuid,
    })
}

impl FileTaskEndpointIdentityProvider for SystemFileTaskEndpointIdentityProvider {
    fn capture(
        &self,
        anchor: &std::path::Path,
    ) -> Result<super::file_task_runtime::DurableEndpointVolumeIdentity, String> {
        #[cfg(all(test, target_os = "linux"))]
        if let Some(identity) = FILE_TASK_ENDPOINT_IDENTITY_OVERRIDES
            .with(|overrides| overrides.borrow().get(anchor).cloned())
        {
            return Ok(identity);
        }
        // Resolve the endpoint anchor before taking its filesystem identity so a
        // symlinked or junction-backed mount is identified by the attached target
        // volume, not by the local filesystem that stores the link itself.
        let resolved_anchor = std::fs::canonicalize(anchor).map_err(|error| {
            format!(
                "resolve file-operation endpoint identity anchor {}: {error}",
                anchor.display()
            )
        })?;
        let snapshot = tui_file_picker::snapshot_path(&resolved_anchor).map_err(|error| {
            format!(
                "capture file-operation endpoint identity for {}: {error}",
                anchor.display()
            )
        })?;
        #[cfg(target_os = "linux")]
        {
            let transient_device = match snapshot.identity() {
                tui_file_picker::SourceIdentity::Unix { device, .. } => *device,
            };
            return match linux_file_task_mount_info(&resolved_anchor) {
                Ok(mount) => Ok(
                    super::file_task_runtime::DurableEndpointVolumeIdentity::UnixMount {
                        transient_device,
                        mount_point: mount.mount_point.clone(),
                        stable: linux_stable_endpoint_identity(&mount),
                    },
                ),
                Err(_) => Ok(
                    super::file_task_runtime::DurableEndpointVolumeIdentity::UnixDevice {
                        device: transient_device,
                    },
                ),
            };
        }
        #[cfg(target_os = "macos")]
        {
            let transient_device = match snapshot.identity() {
                tui_file_picker::SourceIdentity::Unix { device, .. } => *device,
            };
            return match macos_file_task_mount_info(&resolved_anchor) {
                Ok(mount) => Ok(
                    super::file_task_runtime::DurableEndpointVolumeIdentity::UnixMount {
                        transient_device,
                        mount_point: mount.mount_point,
                        stable: mount.volume_uuid.map(|uuid| {
                            super::file_task_runtime::DurableUnixEndpointStableIdentity::FilesystemUuid {
                                uuid,
                                filesystem_type: mount.filesystem_type,
                                mount_root: std::path::PathBuf::from("/"),
                            }
                        }),
                    },
                ),
                Err(_) => Ok(
                    super::file_task_runtime::DurableEndpointVolumeIdentity::UnixDevice {
                        device: transient_device,
                    },
                ),
            };
        }
        #[cfg(all(
            unix,
            not(any(target_os = "linux", target_os = "macos"))
        ))]
        {
            return match snapshot.identity() {
                tui_file_picker::SourceIdentity::Unix { device, .. } => Ok(
                    super::file_task_runtime::DurableEndpointVolumeIdentity::UnixDevice {
                        device: *device,
                    },
                ),
            };
        }
        #[cfg(windows)]
        {
            return match snapshot.identity() {
                tui_file_picker::SourceIdentity::Windows { volume_serial, .. } => Ok(
                    super::file_task_runtime::DurableEndpointVolumeIdentity::WindowsVolume {
                        volume_serial: *volume_serial,
                    },
                ),
            };
        }
        #[cfg(not(any(unix, windows)))]
        {
            let _ = snapshot;
            Ok(super::file_task_runtime::DurableEndpointVolumeIdentity::Unsupported)
        }
    }
}

fn capture_file_task_endpoint_volume(
    anchor: &std::path::Path,
) -> Result<super::file_task_runtime::DurableEndpointVolumeIdentity, String> {
    SystemFileTaskEndpointIdentityProvider.capture(anchor)
}

fn capture_file_task_endpoint_identity(
    role: super::file_task_runtime::DurableEndpointRole,
    operation_root: &std::path::Path,
    anchor_start: &std::path::Path,
) -> Result<super::file_task_runtime::DurableEndpointIdentity, String> {
    let anchor_path = nearest_existing_file_task_endpoint_anchor(anchor_start)?;
    let volume = capture_file_task_endpoint_volume(&anchor_path)?;
    Ok(super::file_task_runtime::DurableEndpointIdentity {
        role,
        operation_root: operation_root.to_path_buf(),
        anchor_path,
        volume,
    })
}

fn capture_file_task_endpoint_identities(
    mappings: &[tui_file_picker::PasteMapping],
    destination_root: &std::path::Path,
) -> Result<Vec<super::file_task_runtime::DurableEndpointIdentity>, String> {
    let mut identities = Vec::with_capacity(mappings.len().saturating_add(1));
    for mapping in mappings {
        let anchor_start = mapping
            .source
            .parent()
            .filter(|parent| !parent.as_os_str().is_empty())
            .unwrap_or(mapping.source.as_path());
        identities.push(capture_file_task_endpoint_identity(
            super::file_task_runtime::DurableEndpointRole::Source,
            &mapping.source,
            anchor_start,
        )?);
    }
    identities.push(capture_file_task_endpoint_identity(
        super::file_task_runtime::DurableEndpointRole::Destination,
        destination_root,
        destination_root,
    )?);
    Ok(identities)
}

fn compare_file_task_endpoint_volumes(
    recorded: &super::file_task_runtime::DurableEndpointVolumeIdentity,
    current: &super::file_task_runtime::DurableEndpointVolumeIdentity,
) -> Result<(), String> {
    use super::file_task_runtime::DurableEndpointVolumeIdentity as Volume;
    match (recorded, current) {
        (
            Volume::UnixMount {
                transient_device: recorded_device,
                mount_point: recorded_mount,
                stable: recorded_stable,
            },
            Volume::UnixMount {
                transient_device: current_device,
                mount_point: current_mount,
                stable: current_stable,
            },
        ) => {
            if recorded_mount != current_mount {
                return Err(format!(
                    "the active mount boundary changed from {} to {}",
                    recorded_mount.display(),
                    current_mount.display()
                ));
            }
            match (recorded_stable, current_stable) {
                (Some(recorded_stable), Some(current_stable)) if recorded_stable == current_stable => {
                    Ok(())
                }
                (Some(_), Some(_)) => Err(
                    "the stable filesystem or mount-source identity changed".to_string(),
                ),
                (Some(_), None) => Err(
                    "the recorded stable endpoint identity is not currently observable".to_string(),
                ),
                (None, _) if recorded_device == current_device => Ok(()),
                (None, _) => Err(format!(
                    "the endpoint device changed from {recorded_device} to {current_device}, but no stable identity is available; attachment is ambiguous"
                )),
            }
        }
        (
            Volume::UnixMount {
                transient_device: recorded,
                stable: Some(_),
                ..
            },
            Volume::UnixDevice { device: current },
        ) => Err(format!(
            "the recorded stable endpoint identity is not currently observable (device {recorded} -> {current}); attachment is ambiguous"
        )),
        (
            Volume::UnixMount {
                transient_device: recorded,
                stable: None,
                ..
            },
            Volume::UnixDevice { device: current },
        ) => Err(format!(
            "the active mount boundary is not currently observable (device {recorded} -> {current}); attachment is ambiguous"
        )),
        (Volume::UnixDevice { device: recorded }, Volume::UnixDevice { device: current })
            if recorded == current =>
        {
            Ok(())
        }
        (
            Volume::UnixDevice { device: recorded },
            Volume::UnixMount {
                transient_device: current,
                ..
            },
        ) if recorded == current => Ok(()),
        (Volume::UnixDevice { device: recorded }, Volume::UnixDevice { device: current })
        | (
            Volume::UnixDevice { device: recorded },
            Volume::UnixMount {
                transient_device: current,
                ..
            },
        ) => Err(format!(
            "the legacy endpoint device changed from {recorded} to {current}; attachment is ambiguous without a stable identity"
        )),
        (
            Volume::WindowsVolume {
                volume_serial: recorded,
            },
            Volume::WindowsVolume {
                volume_serial: current,
            },
        ) if recorded == current => Ok(()),
        (Volume::WindowsVolume { .. }, Volume::WindowsVolume { .. }) => {
            Err("the Windows volume serial changed".to_string())
        }
        (Volume::Unsupported, _) | (_, Volume::Unsupported) => Err(
            "this platform cannot prove a stable endpoint identity".to_string(),
        ),
        _ => Err("the endpoint identity kind changed".to_string()),
    }
}

fn verify_file_task_endpoint_attached_with<P: FileTaskEndpointIdentityProvider>(
    provider: &P,
    endpoint: &super::file_task_runtime::DurableEndpointIdentity,
) -> Result<(), String> {
    match file_task_path_presence(&endpoint.anchor_path) {
        FileTaskPathPresence::Missing => {
            return Err(format!(
                "recorded {:?} endpoint is not attached at {}",
                endpoint.role,
                endpoint.anchor_path.display()
            ))
        }
        FileTaskPathPresence::Unavailable(error) => {
            return Err(format!(
                "recorded {:?} endpoint at {} is unavailable: {error}",
                endpoint.role,
                endpoint.anchor_path.display()
            ))
        }
        FileTaskPathPresence::Present => {}
    }
    let current = provider.capture(&endpoint.anchor_path)?;
    compare_file_task_endpoint_volumes(&endpoint.volume, &current).map_err(|reason| {
        format!(
            "recorded {:?} endpoint at {} is not safely reattached: {reason}",
            endpoint.role,
            endpoint.anchor_path.display()
        )
    })
}

fn verify_file_task_endpoint_attached(
    endpoint: &super::file_task_runtime::DurableEndpointIdentity,
) -> Result<(), String> {
    verify_file_task_endpoint_attached_with(&SystemFileTaskEndpointIdentityProvider, endpoint)
}

fn source_endpoint_identity<'a>(
    record: &'a super::file_task_runtime::DurableFileTaskRecord,
    source: &std::path::Path,
) -> Option<&'a super::file_task_runtime::DurableEndpointIdentity> {
    record.endpoint_identities.iter().find(|endpoint| {
        endpoint.role == super::file_task_runtime::DurableEndpointRole::Source
            && endpoint.operation_root == source
    })
}

fn destination_endpoint_identity<'a>(
    record: &'a super::file_task_runtime::DurableFileTaskRecord,
    destination_root: &std::path::Path,
) -> Option<&'a super::file_task_runtime::DurableEndpointIdentity> {
    record.endpoint_identities.iter().find(|endpoint| {
        endpoint.role == super::file_task_runtime::DurableEndpointRole::Destination
            && (endpoint.operation_root == destination_root
                || destination_root.starts_with(&endpoint.operation_root))
    })
}

struct FileTaskEndpointVerificationCache<'a> {
    record: &'a super::file_task_runtime::DurableFileTaskRecord,
    results: std::collections::BTreeMap<(bool, std::path::PathBuf), Result<(), String>>,
}

impl<'a> FileTaskEndpointVerificationCache<'a> {
    fn new(record: &'a super::file_task_runtime::DurableFileTaskRecord) -> Self {
        Self {
            record,
            results: std::collections::BTreeMap::new(),
        }
    }

    fn verify_endpoint(
        &mut self,
        endpoint: &super::file_task_runtime::DurableEndpointIdentity,
    ) -> Result<(), String> {
        let key = (
            endpoint.role == super::file_task_runtime::DurableEndpointRole::Destination,
            endpoint.operation_root.clone(),
        );
        self.results
            .entry(key)
            .or_insert_with(|| verify_file_task_endpoint_attached(endpoint))
            .clone()
    }

    fn source(&mut self, source: &std::path::Path) -> Result<(), String> {
        let endpoint = source_endpoint_identity(self.record, source)
            .ok_or_else(|| {
                format!(
                    "file-operation journal has no source endpoint identity for {}",
                    source.display()
                )
            })?
            .clone();
        self.verify_endpoint(&endpoint)
    }

    fn destination(&mut self, destination: &std::path::Path) -> Result<(), String> {
        let endpoint = destination_endpoint_identity(self.record, destination)
            .ok_or_else(|| {
                format!(
                    "file-operation journal has no destination endpoint identity for {}",
                    destination.display()
                )
            })?
            .clone();
        self.verify_endpoint(&endpoint)
    }
}

fn common_source_root(sources: &[std::path::PathBuf]) -> Option<std::path::PathBuf> {
    match sources {
        [] => None,
        [single] => Some(single.clone()),
        many => {
            let first_parent = many.first()?.parent()?.to_path_buf();
            if many.iter().all(|path| path.parent() == Some(first_parent.as_path())) {
                Some(first_parent)
            } else {
                None
            }
        }
    }
}

static FILE_TASK_TEMP_COUNTER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

fn sync_file_task_directory(path: &std::path::Path) -> std::io::Result<()> {
    #[cfg(unix)]
    {
        if tui_file_picker::filesystem_capabilities(path).directory_sync
            == tui_file_picker::CapabilitySupport::Unsupported
        {
            return Err(std::io::Error::new(
                std::io::ErrorKind::Unsupported,
                "directory synchronization is unsupported on this mount",
            ));
        }
        let result = std::fs::File::open(path).and_then(|directory| directory.sync_all());
        let support = match &result {
            Ok(()) => tui_file_picker::CapabilitySupport::Supported,
            Err(error)
                if error.kind() == std::io::ErrorKind::Unsupported
                    || matches!(
                        error.raw_os_error(),
                        Some(libc::EINVAL) | Some(libc::EOPNOTSUPP)
                    ) =>
            {
                tui_file_picker::CapabilitySupport::Unsupported
            }
            Err(_) => tui_file_picker::CapabilitySupport::Unknown,
        };
        tui_file_picker::record_filesystem_capability(
            path,
            tui_file_picker::FilesystemCapabilityKind::DirectorySync,
            support,
        );
        result
    }
    #[cfg(not(unix))]
    {
        let _ = path;
        Ok(())
    }
}

fn preserve_file_task_metadata(
    source: &std::path::Path,
    destination: &std::path::Path,
    metadata: &std::fs::Metadata,
) -> Vec<String> {
    let mut warnings = Vec::new();

    #[cfg(unix)]
    {
        use std::ffi::CString;
        use std::os::unix::ffi::OsStrExt;
        use std::os::unix::fs::MetadataExt;

        match CString::new(destination.as_os_str().as_bytes()) {
            Ok(destination_c) => {
                if unsafe { libc::chown(destination_c.as_ptr(), metadata.uid(), metadata.gid()) } != 0 {
                    warnings.push(format!("ownership: {}", std::io::Error::last_os_error()));
                }
                let times = [
                    libc::timespec {
                        tv_sec: metadata.atime(),
                        tv_nsec: metadata.atime_nsec() as _,
                    },
                    libc::timespec {
                        tv_sec: metadata.mtime(),
                        tv_nsec: metadata.mtime_nsec() as _,
                    },
                ];
                if unsafe {
                    libc::utimensat(
                        libc::AT_FDCWD,
                        destination_c.as_ptr(),
                        times.as_ptr(),
                        0,
                    )
                } != 0
                {
                    warnings.push(format!("timestamps: {}", std::io::Error::last_os_error()));
                }
            }
            Err(_) => warnings.push("destination path contains NUL".to_string()),
        }

        #[cfg(target_os = "linux")]
        warnings.extend(copy_file_task_linux_xattrs(source, destination));
    }

    if let Err(error) = std::fs::set_permissions(destination, metadata.permissions()) {
        warnings.push(format!("permissions: {error}"));
    }
    warnings
}

#[cfg(target_os = "linux")]
fn copy_file_task_linux_xattrs(
    source: &std::path::Path,
    destination: &std::path::Path,
) -> Vec<String> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;

    let mut warnings = Vec::new();
    let source_c = match CString::new(source.as_os_str().as_bytes()) {
        Ok(path) => path,
        Err(_) => return vec!["source path contains NUL while copying extended attributes".to_string()],
    };
    let destination_c = match CString::new(destination.as_os_str().as_bytes()) {
        Ok(path) => path,
        Err(_) => {
            return vec!["destination path contains NUL while copying extended attributes".to_string()]
        }
    };
    let size = unsafe { libc::listxattr(source_c.as_ptr(), std::ptr::null_mut(), 0) };
    if size < 0 {
        let error = std::io::Error::last_os_error();
        if error.raw_os_error() != Some(libc::EOPNOTSUPP) {
            warnings.push(format!("list extended attributes: {error}"));
        }
        return warnings;
    }
    if size == 0 {
        return warnings;
    }

    let mut names = vec![0u8; size as usize];
    let read = unsafe {
        libc::listxattr(
            source_c.as_ptr(),
            names.as_mut_ptr().cast(),
            names.len(),
        )
    };
    if read < 0 {
        warnings.push(format!(
            "read extended attribute names: {}",
            std::io::Error::last_os_error()
        ));
        return warnings;
    }

    for raw_name in names[..read as usize]
        .split(|byte| *byte == 0)
        .filter(|name| !name.is_empty())
    {
        let name = match CString::new(raw_name) {
            Ok(name) => name,
            Err(_) => {
                warnings.push("extended attribute name contains NUL".to_string());
                continue;
            }
        };
        let value_size = unsafe {
            libc::getxattr(
                source_c.as_ptr(),
                name.as_ptr(),
                std::ptr::null_mut(),
                0,
            )
        };
        if value_size < 0 {
            warnings.push(format!(
                "read extended attribute {:?}: {}",
                String::from_utf8_lossy(raw_name),
                std::io::Error::last_os_error()
            ));
            continue;
        }
        let mut value = vec![0u8; value_size as usize];
        if value_size > 0 {
            let got = unsafe {
                libc::getxattr(
                    source_c.as_ptr(),
                    name.as_ptr(),
                    value.as_mut_ptr().cast(),
                    value.len(),
                )
            };
            if got < 0 {
                warnings.push(format!(
                    "read extended attribute {:?}: {}",
                    String::from_utf8_lossy(raw_name),
                    std::io::Error::last_os_error()
                ));
                continue;
            }
            value.truncate(got as usize);
        }
        if unsafe {
            libc::setxattr(
                destination_c.as_ptr(),
                name.as_ptr(),
                value.as_ptr().cast(),
                value.len(),
                0,
            )
        } != 0
        {
            warnings.push(format!(
                "write extended attribute {:?}: {}",
                String::from_utf8_lossy(raw_name),
                std::io::Error::last_os_error()
            ));
        }
    }
    warnings
}


#[cfg(unix)]
fn create_private_file_task_directory(path: &std::path::Path) -> std::io::Result<()> {
    use std::os::unix::fs::DirBuilderExt;

    let mut builder = std::fs::DirBuilder::new();
    builder.mode(0o700);
    builder.create(path)
}

#[cfg(not(unix))]
fn create_private_file_task_directory(path: &std::path::Path) -> std::io::Result<()> {
    std::fs::create_dir(path)
}

fn create_file_task_staging_directory(
    parent: &std::path::Path,
    target: &std::path::Path,
    operation: Option<(&str, u64)>,
    journal: Option<&super::file_task_runtime::FileTaskJournalHandle>,
) -> Result<std::path::PathBuf, String> {
    let target_name = target
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| "directory".to_string());
    let pid = std::process::id();
    for _ in 0..128 {
        let nonce = FILE_TASK_TEMP_COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let operation_token = operation
            .map(|(job_id, generation)| format!("-{job_id}-{generation}"))
            .unwrap_or_default();
        let candidate = parent.join(format!(
            ".{}.tonepoet-tree{}-{}-{}.tmp",
            target_name, operation_token, pid, nonce
        ));
        if let Some(journal) = journal {
            journal.record_temp_directory_artifact(&candidate, target)?;
        }
        match create_private_file_task_directory(&candidate) {
            Ok(()) => return Ok(candidate),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&candidate);
                }
            }
            Err(error) => {
                if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&candidate);
                }
                return Err(format!(
                    "create staging directory {}: {error}",
                    candidate.display()
                ));
            }
        }
    }
    Err(format!(
        "could not reserve a staging directory for {}",
        target.display()
    ))
}

fn cleanup_file_task_staging_directory(path: &std::path::Path) -> bool {
    match std::fs::remove_dir_all(path) {
        Ok(()) => true,
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => true,
        Err(error) => {
            log::warn!(
                "could not remove file-task staging directory {}: {error}",
                path.display()
            );
            false
        }
    }
}

fn create_temp_output_file(
    target: &std::path::Path,
    operation: Option<(&str, u64)>,
    journal: Option<&super::file_task_runtime::FileTaskJournalHandle>,
) -> Result<(std::path::PathBuf, std::fs::File), String> {
    let parent = target
        .parent()
        .ok_or_else(|| format!("target has no parent directory: {}", target.display()))?;
    let file_name = target
        .file_name()
        .map(|name| name.to_string_lossy().into_owned())
        .unwrap_or_else(|| "file".to_string());
    let pid = std::process::id();
    for _ in 0..128 {
        let nonce = FILE_TASK_TEMP_COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let operation_token = operation
            .map(|(job_id, generation)| format!("-{job_id}-{generation}"))
            .unwrap_or_default();
        let temp_name = format!(
            ".{}.tonepoet-part{}-{}-{}.tmp",
            file_name, operation_token, pid, nonce
        );
        let temp_path = parent.join(temp_name);
        if let Some(journal) = journal {
            journal.record_temp_artifact(&temp_path, target)?;
        }
        match std::fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temp_path)
        {
            Ok(file) => return Ok((temp_path, file)),
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&temp_path);
                }
            }
            Err(error) => {
                if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&temp_path);
                }
                return Err(format!("create temporary target: {error}"));
            }
        }
    }
    Err(format!(
        "could not create a unique temporary target for {}",
        target.display()
    ))
}

fn cleanup_temp_file(path: &std::path::Path) {
    let _ = std::fs::remove_file(path);
}


/// Fast atomic attempt to move `source` to `target` without replacement.
/// The public wrapper below supplies the documented checked best-effort
/// degraded mode when this primitive is unsupported by the filesystem.
#[cfg(target_os = "linux")]
fn try_atomic_no_clobber_rename(
    source: &std::path::Path,
    target: &std::path::Path,
) -> std::io::Result<()> {
    use std::ffi::CString;
    use std::os::unix::ffi::OsStrExt;

    let old = CString::new(source.as_os_str().as_bytes()).map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("source path contains NUL: {}", source.display()),
        )
    })?;
    let new = CString::new(target.as_os_str().as_bytes()).map_err(|_| {
        std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            format!("target path contains NUL: {}", target.display()),
        )
    })?;

    // Linux renameat2 flag value. libc does not expose RENAME_NOREPLACE on all
    // targets, so keep the constant local and documented.
    const RENAME_NOREPLACE: libc::c_uint = 1;
    let rc = unsafe {
        libc::syscall(
            libc::SYS_renameat2,
            libc::AT_FDCWD,
            old.as_ptr(),
            libc::AT_FDCWD,
            new.as_ptr(),
            RENAME_NOREPLACE,
        )
    };
    if rc == 0 {
        return Ok(());
    }

    let error = std::io::Error::last_os_error();
    match error.raw_os_error() {
        Some(libc::EEXIST) => Err(std::io::Error::new(
            std::io::ErrorKind::AlreadyExists,
            error,
        )),
        Some(libc::EXDEV) => Err(error),
        Some(libc::ENOSYS) | Some(libc::EINVAL) | Some(libc::EOPNOTSUPP) => {
            Err(std::io::Error::new(
                std::io::ErrorKind::Unsupported,
                "atomic no-clobber rename is not supported by this kernel/filesystem",
            ))
        }
        _ => Err(error),
    }
}

#[cfg(windows)]
fn try_atomic_no_clobber_rename(
    source: &std::path::Path,
    target: &std::path::Path,
) -> std::io::Result<()> {
    // MoveFileEx without MOVEFILE_REPLACE_EXISTING is the behavior used by
    // std::fs::rename on Windows: an existing destination is not replaced.
    std::fs::rename(source, target)
}

#[cfg(not(any(target_os = "linux", windows)))]
fn try_atomic_no_clobber_rename(
    source: &std::path::Path,
    target: &std::path::Path,
) -> std::io::Result<()> {
    let _ = (source, target);
    Err(std::io::Error::new(
        std::io::ErrorKind::Unsupported,
        "atomic no-clobber rename is not available on this platform",
    ))
}


#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum NoClobberRenameMode {
    Atomic,
    /// The filesystem rejected the atomic no-replace primitive. The target was
    /// checked for absence immediately before a plain rename. This preserves a
    /// pragmatic no-clobber posture on CIFS, NTFS/FUSE, and similar mounts while
    /// honestly acknowledging the narrow probe-to-rename race.
    CheckedBestEffort,
}

impl NoClobberRenameMode {
    fn degraded_warning(self) -> Option<&'static str> {
        matches!(self, Self::CheckedBestEffort).then_some(
            "filesystem lacks atomic no-clobber rename; used a checked best-effort rename",
        )
    }
}

fn checked_best_effort_no_clobber_rename(
    source: &std::path::Path,
    target: &std::path::Path,
) -> std::io::Result<NoClobberRenameMode> {
    match std::fs::symlink_metadata(target) {
        Ok(_) => {
            return Err(std::io::Error::new(
                std::io::ErrorKind::AlreadyExists,
                format!("destination already exists: {}", target.display()),
            ));
        }
        Err(probe) if probe.kind() == std::io::ErrorKind::NotFound => {}
        Err(probe) => return Err(probe),
    }
    std::fs::rename(source, target)?;
    Ok(NoClobberRenameMode::CheckedBestEffort)
}

#[cfg_attr(not(test), allow(dead_code))] // retained fallback-injection test seam
fn try_no_clobber_rename_with<F>(
    source: &std::path::Path,
    target: &std::path::Path,
    atomic_rename: F,
) -> std::io::Result<NoClobberRenameMode>
where
    F: FnOnce(&std::path::Path, &std::path::Path) -> std::io::Result<()>,
{
    match atomic_rename(source, target) {
        Ok(()) => Ok(NoClobberRenameMode::Atomic),
        Err(error) if error.kind() == std::io::ErrorKind::Unsupported => {
            checked_best_effort_no_clobber_rename(source, target)
        }
        Err(error) => Err(error),
    }
}

fn try_no_clobber_rename(
    source: &std::path::Path,
    target: &std::path::Path,
) -> std::io::Result<NoClobberRenameMode> {
    if tui_file_picker::filesystem_capabilities(target).atomic_no_replace_rename
        == tui_file_picker::CapabilitySupport::Unsupported
    {
        return checked_best_effort_no_clobber_rename(source, target);
    }
    match try_atomic_no_clobber_rename(source, target) {
        Ok(()) => {
            tui_file_picker::record_filesystem_capability(
                target,
                tui_file_picker::FilesystemCapabilityKind::AtomicNoReplaceRename,
                tui_file_picker::CapabilitySupport::Supported,
            );
            Ok(NoClobberRenameMode::Atomic)
        }
        Err(error) if error.kind() == std::io::ErrorKind::Unsupported => {
            tui_file_picker::record_filesystem_capability(
                target,
                tui_file_picker::FilesystemCapabilityKind::AtomicNoReplaceRename,
                tui_file_picker::CapabilitySupport::Unsupported,
            );
            checked_best_effort_no_clobber_rename(source, target)
        }
        Err(error) => {
            if error.kind() == std::io::ErrorKind::AlreadyExists {
                tui_file_picker::record_filesystem_capability(
                    target,
                    tui_file_picker::FilesystemCapabilityKind::AtomicNoReplaceRename,
                    tui_file_picker::CapabilitySupport::Supported,
                );
            }
            Err(error)
        }
    }
}

fn is_cross_device_error(error: &std::io::Error) -> bool {
    is_cross_device_raw_os_error(error.raw_os_error())
        || {
            let message = error.to_string().to_lowercase();
            message.contains("cross-device") || message.contains("not same device")
        }
}

#[cfg(unix)]
fn is_cross_device_raw_os_error(code: Option<i32>) -> bool {
    code == Some(libc::EXDEV)
}

#[cfg(windows)]
fn is_cross_device_raw_os_error(code: Option<i32>) -> bool {
    // Windows ERROR_NOT_SAME_DEVICE. Keep this local instead of depending on a
    // platform bindings crate from this TUI module.
    const ERROR_NOT_SAME_DEVICE: i32 = 17;
    code == Some(ERROR_NOT_SAME_DEVICE)
}

#[cfg(not(any(unix, windows)))]
fn is_cross_device_raw_os_error(_code: Option<i32>) -> bool {
    false
}

fn finalize_temp_file(
    temp_path: &std::path::Path,
    target: &std::path::Path,
    replace_existing: bool,
    verbose_degrade_notices: bool,
) -> Result<Vec<String>, String> {
    if replace_existing {
        replace_temp_file(temp_path, target)?;
        return Ok(Vec::new());
    }
    persist_temp_file_no_clobber(temp_path, target, verbose_degrade_notices)
}

/// Persist a completed temporary file to its final destination without ever
/// clobbering an existing path. The preferred same-directory hard-link publish
/// fails atomically if `target` exists. The fallback reserves `target` with
/// `create_new(true)`, which also cannot overwrite a concurrently-created file.
fn persist_temp_file_no_clobber(
    temp_path: &std::path::Path,
    target: &std::path::Path,
    verbose_degrade_notices: bool,
) -> Result<Vec<String>, String> {
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("mkdir parent: {e}"))?;
    }

    let identity_policy = tui_file_picker::filesystem_identity_policy(target);
    match std::fs::hard_link(temp_path, target) {
        Ok(()) => {
            let warnings = verbose_degrade_notices
                .then(|| tui_file_picker::filesystem_identity_policy_notice(target))
                .flatten()
                .into_iter()
                .collect::<Vec<_>>();
            let temporary_identity = tui_file_picker::snapshot_path(temp_path)
                .map_err(|error| format!("identify completed temporary file: {error}"))?;
            let target_identity = tui_file_picker::snapshot_path(target)
                .map_err(|error| format!("identify hard-link destination {}: {error}", target.display()))?;
            temporary_identity
                .verify_same_identity_with_policy(&target_identity, identity_policy)
                .map_err(|error| format!(
                    "hard-link destination no longer names the published file: {error}"
                ))?;
            cleanup_temp_file(temp_path);
            let final_path_identity = tui_file_picker::snapshot_path(target)
                .map_err(|error| format!(
                    "re-identify hard-link destination {} immediately before success: {error}",
                    target.display()
                ))?;
            target_identity
                .verify_same_identity_with_policy(&final_path_identity, identity_policy)
                .map_err(|error| format!(
                    "hard-link destination changed before publication completed: {error}"
                ))?;
            return Ok(warnings);
        }
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            return Err(format!("destination exists: {}", target.display()));
        }
        Err(_) => {
            // Filesystems such as some network mounts may not support hard links.
            // Reserve the final path with create_new so this fallback still has
            // true no-clobber behavior. If copying into the reserved file fails,
            // remove only that reserved file, which this function created.
        }
    }

    let mut reserved = std::fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(target)
        .map_err(|e| {
            if e.kind() == std::io::ErrorKind::AlreadyExists {
                format!("destination exists: {}", target.display())
            } else {
                format!("reserve destination {}: {e}", target.display())
            }
        })?;
    let reserved_identity = tui_file_picker::snapshot_open_file(&reserved)
        .map_err(|e| format!("identify reserved destination {}: {e}", target.display()))?;
    let copy_result = (|| -> Result<Vec<String>, String> {
        let mut input = std::fs::File::open(temp_path).map_err(|e| format!("open temp: {e}"))?;
        std::io::copy(&mut input, &mut reserved).map_err(|e| format!("publish temp: {e}"))?;
        std::io::Write::flush(&mut reserved).map_err(|e| format!("flush published file: {e}"))?;
        let warnings = tui_file_picker::preserve_open_file_metadata(&input, &reserved);
        reserved.sync_all().map_err(|e| format!("sync published file: {e}"))?;
        let final_handle_identity = tui_file_picker::snapshot_open_file(&reserved)
            .map_err(|e| format!("re-identify reserved destination handle: {e}"))?;
        reserved_identity
            .verify_same_identity(&final_handle_identity)
            .map_err(|e| format!("reserved destination handle identity changed: {e}"))?;
        let final_path_identity = tui_file_picker::snapshot_path(target)
            .map_err(|e| format!("re-identify final destination path {}: {e}", target.display()))?;
        reserved_identity
            .verify_same_identity_with_policy(&final_path_identity, identity_policy)
            .map_err(|e| format!(
                "final destination path no longer names the file reserved by this operation: {e}"
            ))?;
        let mut warnings = warnings;
        if verbose_degrade_notices {
            warnings.extend(tui_file_picker::filesystem_identity_policy_notice(target));
        }
        Ok(warnings)
    })();
    drop(reserved);
    let warnings = match copy_result {
        Ok(warnings) => warnings,
        Err(error) => {
            cleanup_reserved_destination_if_ours(target, &reserved_identity);
            return Err(error);
        }
    };
    cleanup_temp_file(temp_path);
    let final_path_identity = tui_file_picker::snapshot_path(target)
        .map_err(|error| format!(
            "re-identify reserved destination {} immediately before success: {error}",
            target.display()
        ))?;
    reserved_identity
        .verify_same_identity_with_policy(&final_path_identity, identity_policy)
        .map_err(|error| format!(
            "final destination path changed after the reserved handle was closed: {error}"
        ))?;
    Ok(warnings)
}

/// Remove a fallback-created destination only when the final pathname still
/// names the exact object reserved by this operation.  If identity cannot be
/// proven, leave the path untouched for manual recovery.
fn cleanup_reserved_destination_if_ours(
    target: &std::path::Path,
    reserved_identity: &tui_file_picker::SourceSnapshot,
) {
    let Ok(current) = tui_file_picker::snapshot_path(target) else {
        return;
    };
    if reserved_identity.verify_same_identity(&current).is_ok() {
        let _ = std::fs::remove_file(target);
    }
}

fn replace_temp_file(temp_path: &std::path::Path, target: &std::path::Path) -> Result<(), String> {
    if let Ok(target_meta) = std::fs::symlink_metadata(target) {
        if target_meta.file_type().is_dir() {
            return Err(format!("destination is a directory: {}", target.display()));
        }
    }

    #[cfg(windows)]
    if std::fs::symlink_metadata(target).is_ok() {
        remove_existing_file_or_symlink(target).map_err(|e| format!("replace target: {e}"))?;
    }

    std::fs::rename(temp_path, target).map_err(|e| format!("rename temporary target: {e}"))
}

fn remove_existing_file_or_symlink(path: &std::path::Path) -> std::io::Result<()> {
    let meta = std::fs::symlink_metadata(path)?;
    let file_type = meta.file_type();
    if file_type.is_dir() {
        return std::fs::remove_dir(path);
    }
    #[cfg(windows)]
    if file_type.is_symlink() && std::fs::metadata(path).map(|m| m.is_dir()).unwrap_or(false) {
        return std::fs::remove_dir(path);
    }
    std::fs::remove_file(path)
}

fn deterministic_non_conflicting_path(
    target: &std::path::Path,
    _item_kind: tui_file_picker::ConflictItemKind,
) -> std::path::PathBuf {
    if std::fs::symlink_metadata(target).is_err() {
        return target.to_path_buf();
    }
    let parent = target.parent().unwrap_or_else(|| std::path::Path::new("."));
    let stem = target
        .file_stem()
        .and_then(|stem| stem.to_str())
        .unwrap_or("item");
    let extension = target.extension().and_then(|ext| ext.to_str());
    for idx in 1u64..10_000 {
        let suffix = if idx == 1 {
            " copy".to_string()
        } else {
            format!(" copy {}", idx)
        };
        let name = match extension {
            Some(ext) if !ext.is_empty() => format!("{}{}.{}", stem, suffix, ext),
            _ => format!("{}{}", stem, suffix),
        };
        let candidate = parent.join(name);
        if std::fs::symlink_metadata(&candidate).is_err() {
            return candidate;
        }
    }
    parent.join(format!("{} copy {}", stem, FILE_TASK_TEMP_COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed)))
}

fn item_kind_label(kind: tui_file_picker::ConflictItemKind) -> &'static str {
    match kind {
        tui_file_picker::ConflictItemKind::File => "file",
        tui_file_picker::ConflictItemKind::Directory => "directory",
        tui_file_picker::ConflictItemKind::Symlink => "symlink",
        tui_file_picker::ConflictItemKind::Other => "item",
    }
}


fn conflict_item_kind_for_plan(node: &FileTaskPlanNode) -> tui_file_picker::ConflictItemKind {
    match node.kind {
        FileTaskPlanKind::File => tui_file_picker::ConflictItemKind::File,
        FileTaskPlanKind::Directory => tui_file_picker::ConflictItemKind::Directory,
        FileTaskPlanKind::Symlink => tui_file_picker::ConflictItemKind::Symlink,
    }
}


fn count_existing_conflicts(nodes: &[FileTaskPlanNode]) -> u64 {
    nodes
        .iter()
        .map(|node| {
            if std::fs::symlink_metadata(&node.target).is_ok() {
                // A pre-existing target is one user-visible conflict group. If this
                // is a directory, the resolution chosen for that directory (overwrite,
                // skip, rename, or abort) determines the whole subtree, and scoped
                // overwrite auto-resolves descendant conflicts without another prompt.
                1
            } else {
                count_existing_conflicts(&node.children)
            }
        })
        .sum()
}

fn conflict_incoming_display_size(
    node: &FileTaskPlanNode,
    metadata: Option<&std::fs::Metadata>,
) -> Option<u64> {
    match node.kind {
        FileTaskPlanKind::Directory => Some(node.stats.bytes),
        FileTaskPlanKind::File => metadata.map(|meta| meta.len()).or(Some(node.stats.bytes)),
        FileTaskPlanKind::Symlink => metadata.map(|meta| meta.len()),
    }
}

fn conflict_existing_display_size(metadata: &std::fs::Metadata) -> Option<u64> {
    if metadata.file_type().is_dir() {
        // Directory metadata length is an inode/directory-entry implementation
        // detail, not user-visible content size. The prompt starts with an
        // honest unknown and may be refined by a non-blocking local-filesystem
        // probe if that can finish inside the explicit budget below.
        None
    } else {
        Some(metadata.len())
    }
}

const FILE_TASK_EXISTING_DIR_SIZE_MAX_ENTRIES: u64 = 20_000;
const FILE_TASK_EXISTING_DIR_SIZE_BUDGET: std::time::Duration = std::time::Duration::from_millis(250);

fn maybe_spawn_existing_directory_size_probe(
    session_id: u64,
    sink: FileTaskEventSink,
    request_id: u64,
    target: &std::path::Path,
    existing_meta: &std::fs::Metadata,
    existing_modified: Option<std::time::SystemTime>,
) {
    if !existing_meta.file_type().is_dir() || !should_probe_existing_directory_size(target) {
        return;
    }

    let target = target.to_path_buf();
    let _ = std::thread::Builder::new()
        .name("file-task-conflict-dir-size".to_string())
        .spawn(move || {
            let Some(size) = measure_existing_directory_size_for_prompt(&target) else {
                return;
            };
            sink.progress(
                session_id,
                tui_file_picker::FileTaskProgressUpdate::UpdateConflictExistingStats {
                    request_id,
                    size,
                    modified: existing_modified,
                },
            );
        });
}

fn should_probe_existing_directory_size(path: &std::path::Path) -> bool {
    // The size probe is a UI refinement only. Be conservative: launch it only
    // when the filesystem looks local. Remote, FUSE, automount, and unknown
    // filesystems keep the initial `--` display so conflict resolution never
    // waits on slow metadata traversal.
    existing_directory_size_probe_filesystem_is_local(path).unwrap_or(false)
}

fn measure_existing_directory_size_for_prompt(path: &std::path::Path) -> Option<u64> {
    let started = std::time::Instant::now();
    let mut stack = vec![path.to_path_buf()];
    let mut entries_seen = 0u64;
    let mut bytes = 0u64;

    while let Some(dir) = stack.pop() {
        if entries_seen >= FILE_TASK_EXISTING_DIR_SIZE_MAX_ENTRIES
            || started.elapsed() >= FILE_TASK_EXISTING_DIR_SIZE_BUDGET
        {
            return None;
        }
        let read_dir = std::fs::read_dir(&dir).ok()?;
        for entry in read_dir {
            if entries_seen >= FILE_TASK_EXISTING_DIR_SIZE_MAX_ENTRIES
                || started.elapsed() >= FILE_TASK_EXISTING_DIR_SIZE_BUDGET
            {
                return None;
            }
            let entry = entry.ok()?;
            entries_seen = entries_seen.saturating_add(1);
            let path = entry.path();
            let metadata = std::fs::symlink_metadata(&path).ok()?;
            if metadata.file_type().is_dir() {
                stack.push(path);
            } else {
                bytes = bytes.saturating_add(metadata.len());
            }
        }
    }

    Some(bytes)
}

#[cfg(target_os = "linux")]
fn existing_directory_size_probe_filesystem_is_local(path: &std::path::Path) -> Option<bool> {
    use std::os::unix::ffi::OsStrExt;

    let c_path = std::ffi::CString::new(path.as_os_str().as_bytes()).ok()?;
    let mut stat: libc::statfs = unsafe { std::mem::zeroed() };
    if unsafe { libc::statfs(c_path.as_ptr(), &mut stat) } != 0 {
        return None;
    }
    Some(!is_remote_or_virtual_filesystem_magic(stat.f_type as i64))
}

#[cfg(not(target_os = "linux"))]
fn existing_directory_size_probe_filesystem_is_local(_path: &std::path::Path) -> Option<bool> {
    // `std` has no portable filesystem-type API. On non-Linux platforms this
    // feature remains conservative until a platform-specific local/remote
    // classifier is added.
    None
}

fn is_remote_or_virtual_filesystem_magic(magic: i64) -> bool {
    matches!(
        magic,
        0x6969       // NFS_SUPER_MAGIC
            | 0x517B // SMB_SUPER_MAGIC
            | 0xFF534D42 // CIFS_MAGIC_NUMBER
            | 0x65735546 // FUSE_SUPER_MAGIC; includes sshfs and many remote/user-space mounts
            | 0x00C36400 // CEPH_SUPER_MAGIC
            | 0x73757245 // CODA_SUPER_MAGIC
            | 0x0000564C // NCP_SUPER_MAGIC
            | 0x5346414F // AFS_SUPER_MAGIC
            | 0x01021997 // 9P_SUPER_MAGIC
            | 0x00000187 // AUTOFS_SUPER_MAGIC
            | 0x00009FA0 // PROC_SUPER_MAGIC
            | 0x62656572 // SYSFS_MAGIC
            | 0x64626720 // DEBUGFS_MAGIC
            | 0x958458F6 // HUGETLBFS_MAGIC
    )
}

fn retarget_plan_node(node: &mut FileTaskPlanNode, new_target: &std::path::Path) {
    node.target = new_target.to_path_buf();
    if matches!(node.kind, FileTaskPlanKind::Directory) {
        let parent_target = node.target.clone();
        for child in &mut node.children {
            if let Some(name) = child.source.file_name().map(|name| name.to_os_string()) {
                let child_target = parent_target.join(name);
                retarget_plan_node(child, &child_target);
            }
        }
    }
}

#[cfg(test)]
fn build_file_task_plan(
    sources: &[std::path::PathBuf],
    dest_dir: &std::path::Path,
) -> Result<FileTaskPlan, String> {
    let mut roots = Vec::with_capacity(sources.len());
    let mut totals = FileTaskPathStats::default();

    for source in sources {
        let file_name = source
            .file_name()
            .ok_or_else(|| format!("source has no file name: {}", source.display()))?
            .to_owned();
        let target = dest_dir.join(file_name);
        let source_type = std::fs::symlink_metadata(source)
            .map_err(|e| format!("stat source {}: {}", source.display(), e))?
            .file_type();
        if source_type.is_dir() {
            ensure_not_copying_dir_into_itself(source, &target)?;
        }
        let node = build_file_task_plan_node(source, &target)?;
        totals.add(node.stats);
        roots.push(node);
    }

    Ok(FileTaskPlan { roots, totals })
}

#[cfg(test)]
fn build_file_task_plan_node(
    source: &std::path::Path,
    target: &std::path::Path,
) -> Result<FileTaskPlanNode, String> {
    let source_snapshot = tui_file_picker::snapshot_path(source)
        .map_err(|e| format!("capture source identity {}: {}", source.display(), e))?;
    if source_snapshot.kind() == tui_file_picker::SourceKind::File {
        let stats = FileTaskPathStats {
            files: 1,
            folders: 0,
            bytes: source_snapshot.len(),
        };
        return Ok(FileTaskPlanNode {
            source: source.to_path_buf(),
            target: target.to_path_buf(),
            kind: FileTaskPlanKind::File,
            stats,
            children: Vec::new(),
            tree_fully_planned: true,
            source_snapshot,
        });
    }
    if source_snapshot.kind() == tui_file_picker::SourceKind::Symlink {
        let stats = FileTaskPathStats { files: 1, folders: 0, bytes: 0 };
        return Ok(FileTaskPlanNode {
            source: source.to_path_buf(),
            target: target.to_path_buf(),
            kind: FileTaskPlanKind::Symlink,
            stats,
            children: Vec::new(),
            tree_fully_planned: true,
            source_snapshot,
        });
    }
    if source_snapshot.kind() == tui_file_picker::SourceKind::Directory {
        let mut stats = FileTaskPathStats { files: 0, folders: 1, bytes: 0 };
        let mut children = Vec::new();
        for entry in std::fs::read_dir(source).map_err(|e| format!("readdir {}: {}", source.display(), e))? {
            let entry = entry.map_err(|e| format!("entry: {e}"))?;
            let child = build_file_task_plan_node(&entry.path(), &target.join(entry.file_name()))?;
            stats.add(child.stats);
            children.push(child);
        }
        return Ok(FileTaskPlanNode {
            source: source.to_path_buf(),
            target: target.to_path_buf(),
            kind: FileTaskPlanKind::Directory,
            stats,
            children,
            tree_fully_planned: true,
            source_snapshot,
        });
    }
    Err(format!(
        "unsupported file type, refusing to plan: {}",
        source.display()
    ))
}


fn build_source_manifest(
    root: &FileTaskPlanNode,
    digests: &std::collections::HashMap<std::path::PathBuf, tui_file_picker::ContentDigest>,
    verification: tui_file_picker::VerificationMode,
) -> Result<tui_file_picker::SourceManifest, String> {
    if matches!(root.kind, FileTaskPlanKind::Directory) && !root.tree_fully_planned {
        return Err(
            "cannot build a source manifest from an unexpanded move directory plan".to_string(),
        );
    }
    fn add_node(
        manifest: &mut tui_file_picker::SourceManifest,
        root_path: &std::path::Path,
        node: &FileTaskPlanNode,
        digests: &std::collections::HashMap<std::path::PathBuf, tui_file_picker::ContentDigest>,
        verification: tui_file_picker::VerificationMode,
    ) -> Result<(), String> {
        let relative = node
            .source
            .strip_prefix(root_path)
            .map_err(|_| format!("source plan escaped root: {}", node.source.display()))?
            .to_path_buf();
        let digest = if verification == tui_file_picker::VerificationMode::Strong
            && matches!(node.kind, FileTaskPlanKind::File)
        {
            Some(*digests.get(&node.source).ok_or_else(|| {
                format!("missing copied-content digest for {}", node.source.display())
            })?)
        } else {
            None
        };
        manifest.insert(relative, node.source_snapshot.clone(), digest)?;
        for child in &node.children {
            add_node(manifest, root_path, child, digests, verification)?;
        }
        Ok(())
    }

    let mut manifest = tui_file_picker::SourceManifest::new(verification);
    add_node(&mut manifest, &root.source, root, digests, verification)?;
    Ok(manifest)
}

fn retarget_source_plan_node(node: &mut FileTaskPlanNode, new_source: &std::path::Path) {
    node.source = new_source.to_path_buf();
    for child in &mut node.children {
        if let Some(name) = child.source.file_name().map(|name| name.to_os_string()) {
            retarget_source_plan_node(child, &new_source.join(name));
        }
    }
}

static SOURCE_QUARANTINE_COUNTER: std::sync::atomic::AtomicU64 =
    std::sync::atomic::AtomicU64::new(0);

fn quarantine_source_root(
    source: &std::path::Path,
    journal: Option<(
        &super::file_task_runtime::FileTaskJournalHandle,
        &std::path::Path,
    )>,
) -> Result<(std::path::PathBuf, NoClobberRenameMode), String> {
    let parent = source.parent().unwrap_or_else(|| std::path::Path::new("."));
    let pid = std::process::id();
    for _ in 0..256 {
        let nonce = SOURCE_QUARANTINE_COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let container = parent.join(format!(
            ".tonepoet-source-quarantine-{pid}-{nonce}"
        ));
        match create_private_file_task_directory(&container) {
            Ok(()) => {}
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(error) => {
                return Err(format!(
                    "could not reserve a private source quarantine beside {}: {error}",
                    source.display()
                ))
            }
        }
        let quarantine = container.join("payload");
        if let Some((journal, destination)) = journal {
            if let Err(error) = journal.record_quarantine_artifact(
                &quarantine,
                source,
                destination,
            ) {
                let _ = std::fs::remove_dir(&container);
                return Err(format!(
                    "could not durably record source quarantine intent for {}: {error}",
                    source.display()
                ));
            }
        }
        match try_no_clobber_rename(source, &quarantine) {
            Ok(mode) => {
                if let Some((journal, _)) = journal {
                    if let Err(error) = journal.mark_quarantine_renamed(&quarantine) {
                        let restore = try_no_clobber_rename(&quarantine, source);
                        if restore.is_ok() {
                            let _ = journal.clear_quarantine_artifact(&quarantine);
                            let _ = std::fs::remove_dir(&container);
                            return Err(format!(
                                "source quarantine completed but its durable rename checkpoint failed; source was restored: {error}"
                            ));
                        }
                        return Err(format!(
                            "source quarantine completed but its durable rename checkpoint failed and immediate restoration also failed; reconciliation must inspect {} and {}: {error}; restore error: {}",
                            source.display(),
                            quarantine.display(),
                            restore.expect_err("restore failure checked above")
                        ));
                    }
                }
                return Ok((quarantine, mode));
            }
            Err(error) => {
                if let Some((journal, _)) = journal {
                    let _ = journal.clear_quarantine_artifact(&quarantine);
                }
                let _ = std::fs::remove_dir(&container);
                return Err(format!(
                    "could not quarantine source {} without replacement: {error}",
                    source.display()
                ));
            }
        }
    }
    Err(format!(
        "could not allocate a private source quarantine beside {}",
        source.display()
    ))
}

fn try_restore_quarantined_source_accounted(
    quarantine: &std::path::Path,
    original: &std::path::Path,
    io_counters: &mut tui_file_picker::FileOperationIoCounters,
) -> (bool, String) {
    io_counters.rename_attempts = io_counters.rename_attempts.saturating_add(1);
    match try_no_clobber_rename(quarantine, original) {
        Ok(mode) => {
            if matches!(mode, NoClobberRenameMode::CheckedBestEffort) {
                io_counters.rename_fallbacks = io_counters.rename_fallbacks.saturating_add(1);
            }
            let mut details = vec![format!("source restored to {}", original.display())];
            if let Some(warning) = mode.degraded_warning() {
                details.push(warning.to_string());
            }
            if let Some(container) = quarantine.parent() {
                if let Err(error) = std::fs::remove_dir(container) {
                    if error.kind() != std::io::ErrorKind::NotFound {
                        details.push(format!(
                            "empty quarantine {} could not be removed: {error}",
                            container.display()
                        ));
                    }
                }
            }
            if let Some(parent) = original.parent() {
                io_counters.directory_sync_calls =
                    io_counters.directory_sync_calls.saturating_add(1);
                if let Err(error) = sync_file_task_directory(parent) {
                    details.push(format!(
                        "restored source parent could not be synchronized: {error}"
                    ));
                }
            }
            (true, details.join("; "))
        }
        Err(error) => (
            false,
            format!(
                "source retained at {} because restoration to {} failed: {error}",
                quarantine.display(),
                original.display()
            ),
        ),
    }
}

fn ensure_not_copying_dir_into_itself(
    source: &std::path::Path,
    target: &std::path::Path,
) -> Result<(), String> {
    let source_canon = source
        .canonicalize()
        .map_err(|e| format!("canonicalize source {}: {}", source.display(), e))?;

    if let Ok(target_canon) = target.canonicalize() {
        if target_canon.starts_with(&source_canon) {
            return Err(format!(
                "refusing to copy or move directory into itself: {} -> {}",
                source.display(),
                target.display()
            ));
        }
        return Ok(());
    }

    if let Some(parent_canon) = canonical_existing_ancestor(target) {
        if parent_canon.starts_with(&source_canon) {
            return Err(format!(
                "refusing to copy or move directory into itself: {} -> {}",
                source.display(),
                target.display()
            ));
        }
    }

    Ok(())
}

fn canonical_existing_ancestor(path: &std::path::Path) -> Option<std::path::PathBuf> {
    let mut cursor = path.parent();
    while let Some(parent) = cursor {
        if let Ok(canonical) = parent.canonicalize() {
            return Some(canonical);
        }
        cursor = parent.parent();
    }
    None
}

#[cfg(test)]
fn verify_copied_path(source: &std::path::Path, target: &std::path::Path) -> Result<(), String> {
    let src_meta = std::fs::symlink_metadata(source)
        .map_err(|e| format!("stat source {}: {}", source.display(), e))?;
    let dst_meta = std::fs::symlink_metadata(target)
        .map_err(|e| format!("stat target {}: {}", target.display(), e))?;
    let src_type = src_meta.file_type();
    let dst_type = dst_meta.file_type();

    if src_type.is_symlink() {
        if !dst_type.is_symlink() {
            return Err(format!("target is not a symlink: {}", target.display()));
        }
        let src_link = std::fs::read_link(source)
            .map_err(|e| format!("read source symlink {}: {}", source.display(), e))?;
        let dst_link = std::fs::read_link(target)
            .map_err(|e| format!("read target symlink {}: {}", target.display(), e))?;
        if src_link != dst_link {
            return Err(format!(
                "symlink target mismatch: {} -> {:?}, {} -> {:?}",
                source.display(),
                src_link,
                target.display(),
                dst_link
            ));
        }
        return Ok(());
    }

    if src_type.is_dir() {
        if !dst_type.is_dir() {
            return Err(format!("target is not a directory: {}", target.display()));
        }
        for entry in std::fs::read_dir(source).map_err(|e| format!("readdir: {}", e))? {
            let entry = entry.map_err(|e| format!("entry: {}", e))?;
            verify_copied_path(&entry.path(), &target.join(entry.file_name()))?;
        }
        return Ok(());
    }

    if src_type.is_file() {
        if !dst_type.is_file() {
            return Err(format!("target is not a regular file: {}", target.display()));
        }
        if src_meta.len() != dst_meta.len() {
            return Err(format!(
                "file size mismatch: {} has {}, {} has {} bytes",
                source.display(),
                src_meta.len(),
                target.display(),
                dst_meta.len()
            ));
        }
        return Ok(());
    }

    Err(format!(
        "unsupported file type, refusing to verify: {}",
        source.display()
    ))
}


#[cfg(unix)]
fn copy_symlink_atomic(
    source: &std::path::Path,
    target: &std::path::Path,
    replace_existing: bool,
    operation: Option<(&str, u64)>,
    journal: Option<&super::file_task_runtime::FileTaskJournalHandle>,
) -> Result<(), String> {
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("mkdir parent: {e}"))?;
    }
    let link_target = std::fs::read_link(source)
        .map_err(|e| format!("read symlink {}: {e}", source.display()))?;

    if !replace_existing {
        return std::os::unix::fs::symlink(&link_target, target).map_err(|e| {
            if e.kind() == std::io::ErrorKind::AlreadyExists {
                format!("destination exists: {}", target.display())
            } else {
                format!("copy symlink: {e}")
            }
        });
    }

    if let Ok(meta) = std::fs::symlink_metadata(target) {
        if meta.file_type().is_dir() {
            return Err(format!("destination is a directory: {}", target.display()));
        }
    }
    let parent = target.parent().unwrap_or_else(|| std::path::Path::new("."));
    let name = target.file_name().and_then(|n| n.to_str()).unwrap_or("link");
    let pid = std::process::id();
    for _ in 0..128 {
        let nonce = FILE_TASK_TEMP_COUNTER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
        let operation_token = operation
            .map(|(job_id, generation)| format!("-{job_id}-{generation}"))
            .unwrap_or_default();
        let temp = parent.join(format!(
            ".{}.tonepoet-link{}-{}-{}.tmp",
            name, operation_token, pid, nonce
        ));
        if let Some(journal) = journal {
            journal.record_temp_symlink_artifact(&temp, target)?;
        }
        match std::os::unix::fs::symlink(&link_target, &temp) {
            Ok(()) => {
                let result = std::fs::rename(&temp, target)
                    .map_err(|e| format!("rename temporary symlink: {e}"));
                if result.is_err() {
                    let removed = match std::fs::remove_file(&temp) {
                        Ok(()) => true,
                        Err(error) if error.kind() == std::io::ErrorKind::NotFound => true,
                        Err(_) => false,
                    };
                    if removed {
                        if let Some(journal) = journal {
                            let _ = journal.clear_temp_artifact(&temp);
                        }
                    }
                } else if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&temp);
                }
                return result;
            }
            Err(error) if error.kind() == std::io::ErrorKind::AlreadyExists => {
                if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&temp);
                }
            }
            Err(error) => {
                if let Some(journal) = journal {
                    let _ = journal.clear_temp_artifact(&temp);
                }
                return Err(format!("copy symlink: {error}"));
            }
        }
    }
    Err(format!(
        "could not create a unique temporary symlink for {}",
        target.display()
    ))
}

#[cfg(windows)]
fn copy_symlink_atomic(
    source: &std::path::Path,
    target: &std::path::Path,
    replace_existing: bool,
    _operation: Option<(&str, u64)>,
    _journal: Option<&super::file_task_runtime::FileTaskJournalHandle>,
) -> Result<(), String> {
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("mkdir parent: {}", e))?;
    }
    if std::fs::symlink_metadata(target).is_ok() {
        if !replace_existing {
            return Err(format!("destination exists: {}", target.display()));
        }
        remove_existing_file_or_symlink(target)
            .map_err(|e| format!("replace target symlink: {}", e))?;
    }
    copy_symlink(source, target)
}

#[cfg(not(any(unix, windows)))]
fn copy_symlink_atomic(
    source: &std::path::Path,
    target: &std::path::Path,
    _replace_existing: bool,
    _operation: Option<(&str, u64)>,
    _journal: Option<&super::file_task_runtime::FileTaskJournalHandle>,
) -> Result<(), String> {
    copy_symlink(source, target)
}

#[cfg(windows)]
fn copy_symlink(source: &std::path::Path, target: &std::path::Path) -> Result<(), String> {
    if let Some(parent) = target.parent() {
        std::fs::create_dir_all(parent).map_err(|e| format!("mkdir parent: {}", e))?;
    }
    let link_target = std::fs::read_link(source)
        .map_err(|e| format!("read symlink {}: {}", source.display(), e))?;
    let create_result = if source.metadata().map(|m| m.is_dir()).unwrap_or(false) {
        std::os::windows::fs::symlink_dir(&link_target, target)
    } else {
        std::os::windows::fs::symlink_file(&link_target, target)
    };
    match create_result {
        Ok(()) => Ok(()),
        Err(e) if e.kind() == std::io::ErrorKind::AlreadyExists => {
            Err(format!("destination exists: {}", target.display()))
        }
        Err(e) => Err(format!("copy symlink: {}", e)),
    }
}


#[cfg(not(any(unix, windows)))]
fn copy_symlink(source: &std::path::Path, _target: &std::path::Path) -> Result<(), String> {
    Err(format!(
        "copying symlinks is not supported on this platform: {}",
        source.display()
    ))
}

