    #[test]
    fn import_cue_refuses_while_the_metadata_editor_is_open() {
        // Audit H4: ImportCue replaced the editor with a GnudbReview that
        // carries no editor session, destroying every unsaved edit.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let state =
            single_image_state(vec![entry("TITLE", ItemKey::TrackTitle, &["One"], &["Orig"])]);
        app.active_overlay = ActiveOverlay::MetadataEditor(Box::new(state));
        let (tx, _rx) = mpsc::channel(4);

        super::super::command::execute_command(
            &mut app,
            super::super::command::Command::ImportCue,
            &tx,
        );

        let ActiveOverlay::MetadataEditor(state) = &app.active_overlay else {
            panic!("the editor session must survive an import-cue attempt");
        };
        assert!(
            state.active_surface().dirty,
            "unsaved edits must be preserved"
        );
        assert!(
            app.status_message
                .as_ref()
                .is_some_and(|(message, _)| message.starts_with("import-cue:")),
            "the refusal must be visible"
        );
    }

    #[test]
    fn import_cue_refuses_over_a_parked_editor_session() {
        // Typing `:` inside the editor PARKS the session and clears the
        // overlay before the command executes — the overlay-only guard let
        // this route install a review that orphaned the parked dirty
        // session. The guard must refuse on pending_metadata_editor too.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let state =
            single_image_state(vec![entry("TITLE", ItemKey::TrackTitle, &["One"], &["Orig"])]);
        app.pending_metadata_editor = Some(Box::new(state));
        app.active_overlay = ActiveOverlay::None; // command-input Enter shape
        let (tx, _rx) = mpsc::channel(4);

        super::super::command::execute_command(
            &mut app,
            super::super::command::Command::ImportCue,
            &tx,
        );

        assert!(
            matches!(app.active_overlay, ActiveOverlay::None),
            "no review may be installed over a parked session"
        );
        let parked = app
            .pending_metadata_editor
            .as_ref()
            .expect("the parked session must survive");
        assert!(parked.active_surface().dirty, "unsaved edits preserved");
        assert!(
            app.status_message
                .as_ref()
                .is_some_and(|(message, _)| message.starts_with("import-cue:")),
        );
    }

    #[test]
    fn import_cue_refuses_over_a_parked_cue_preview() {
        // Same shape for the OTHER parkable session type: the editable
        // cuesheet buffer parks into pending_cue_preview when `:` opens the
        // command input; installing the review would strand it identically.
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.pending_cue_preview = Some(Box::new(crate::tui::app::CuePreviewState::new(
            "FILE \"a.flac\" WAVE\n".to_string(),
            std::path::PathBuf::from("/tmp/a.cue"),
            "edited".to_string(),
        )));
        app.active_overlay = ActiveOverlay::None;
        let (tx, _rx) = mpsc::channel(4);

        super::super::command::execute_command(
            &mut app,
            super::super::command::Command::ImportCue,
            &tx,
        );

        assert!(
            matches!(app.active_overlay, ActiveOverlay::None),
            "no review may be installed over a parked cue-preview session"
        );
        assert!(
            app.pending_cue_preview.is_some(),
            "the parked cue buffer must survive"
        );
        assert!(app
            .status_message
            .as_ref()
            .is_some_and(|(message, _)| message.starts_with("import-cue:")));
    }

    #[test]
    fn editable_cue_preview_cancel_button_closes_preview_without_quitting() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.active_overlay = ActiveOverlay::CuePreview(Box::new(
            crate::tui::app::CuePreviewState::new(
                "FILE \"album.flac\" WAVE\n".to_string(),
                std::path::PathBuf::from("/tmp/album.cue"),
                "editable preview".to_string(),
            ),
        ));
        let area = crossterm::terminal::size().unwrap_or((80, 24));
        let width = ((area.0 as u32 * 80 / 100) as u16)
            .max(60)
            .min(area.0.saturating_sub(2));
        let height = ((area.1 as u32 * 80 / 100) as u16)
            .max(15)
            .min(area.1.saturating_sub(2));
        let x = (area.0.saturating_sub(width)) / 2;
        let y = (area.1.saturating_sub(height)) / 2;
        let click_x = x.saturating_add(1);
        let click_y = y.saturating_add(1);
        app.button_map.record_button(
            super::super::button_map::TuiButton::CuePreviewCancel,
            ratatui::layout::Rect::new(click_x, click_y, 1, 1),
        );
        let (tx, _rx) = tokio::sync::mpsc::channel(4);

        handle_cue_preview_mouse(
            &mut app,
            crossterm::event::MouseEvent {
                kind: crossterm::event::MouseEventKind::Down(
                    crossterm::event::MouseButton::Left,
                ),
                column: click_x,
                row: click_y,
                modifiers: crossterm::event::KeyModifiers::NONE,
            },
            &tx,
        );

        assert!(app.pending_cue_preview.is_none());
        assert!(matches!(app.active_overlay, ActiveOverlay::None));
        assert!(!app.should_quit);
        assert_eq!(
            app.status_message.as_ref().map(|(message, _)| message.as_str()),
            Some("CUE preview cancelled")
        );
    }

