    // ---------- C5 tests: SACD editor surfacing ----------

    /// Build a minimal SacdMetadata with the supplied album+track text
    /// and one stereo area. Used to test `build_sacd_editor_state`
    /// without re-running the full parser.
    fn synth_sacd_metadata(
        album_title: Option<&str>,
        album_artist: Option<&str>,
        disc_year: u16,
        catalog: Option<&str>,
        track_titles: &[&str],
        track_performers: &[&str],
        track_isrcs: &[Option<&str>],
    ) -> crate::tui::sacd::SacdMetadata {
        use crate::tui::sacd::*;

        let master_toc = MasterToc {
            spec_version: (1, 20),
            album_set_size: 1,
            album_sequence_number: 1,
            album_catalog_number: catalog.unwrap_or("").to_string(),
            album_genres: vec![],
            two_channel: AreaPointer {
                toc_1_start: 540,
                toc_2_start: 541,
                toc_size_sectors: 3,
            },
            multi_channel: AreaPointer {
                toc_1_start: 0,
                toc_2_start: 0,
                toc_size_sectors: 0,
            },
            disc_type_hybrid: false,
            disc_catalog_number: String::new(),
            disc_genres: vec![Genre {
                category: 1,
                genre: 14, /* JAZZ */
            }],
            disc_date: if disc_year > 0 {
                Some(DiscDate {
                    year: disc_year,
                    month: 0,
                    day: 0,
                })
            } else {
                None
            },
            text_area_count: 1,
            locales: vec![],
        };

        let master_text = if album_title.is_some() || album_artist.is_some() {
            Some(SacdText {
                album_title: album_title.map(|s| s.to_string()),
                album_artist: album_artist.map(|s| s.to_string()),
                charset: 2,
                ..Default::default()
            })
        } else {
            None
        };

        let n = track_titles.len();
        let mut tracks: Vec<TrackEntry> = Vec::with_capacity(n);
        for i in 0..n {
            tracks.push(TrackEntry {
                start_lsn: 600 + i as u32 * 100,
                length_lsn: 100,
                start_time: PlayTime::default(),
                duration: PlayTime {
                    minutes: 3,
                    seconds: 0,
                    frames: 0,
                },
                text: TrackText {
                    title: if track_titles[i].is_empty() {
                        None
                    } else {
                        Some(track_titles[i].to_string())
                    },
                    performer: track_performers
                        .get(i)
                        .filter(|s| !s.is_empty())
                        .map(|s| s.to_string()),
                    ..Default::default()
                },
                isrc: track_isrcs.get(i).and_then(|o| o.map(|s| s.to_string())),
                structured_isrc: None,
                genre: None,
            });
        }

        let stereo_header = AreaTocHeader {
            kind: AreaKind::Stereo,
            spec_version: (1, 20),
            size_sectors: 3,
            max_byte_rate: 64_000,
            sample_frequency: 0x04,
            frame_format: FrameFormat::Dsd3In14,
            channel_count: 2,
            loudspeaker_config: 0,
            extra_settings: 0,
            max_available_channels: 2,
            area_mute_flags: 0,
            total_playtime: PlayTime {
                minutes: 30,
                seconds: 0,
                frames: 0,
            },
            track_offset: 0,
            track_count: n as u8,
            track_start_lsn: 600,
            track_end_lsn: 10_000,
            text_area_count: 1,
            locales: vec![Locale {
                language_code: [b'e', b'n'],
                character_set: 2,
            }],
            description: None,
            description_phonetic: None,
            copyright: None,
            copyright_phonetic: None,
        };

        SacdMetadata {
            master_toc,
            master_text,
            stereo: Some(AreaInfo {
                header: stereo_header,
                tracks,
                consistency: Default::default(),
            }),
            multi_channel: None,
            consistency: Default::default(),
        }
    }

    #[test]
    fn sacd_and_regular_file_surfaces_share_the_canonical_field_order() {
        let md = synth_sacd_metadata(
            Some("Album"),
            Some("Artist"),
            2026,
            Some("CAT-1"),
            &["One", "Two", "Three"],
            &["Artist", "Artist", "Artist"],
            &[None, None, None],
        );
        let path = std::path::PathBuf::from("/tmp/order.iso");
        let (mut sacd, _, _) = build_sacd_editor_state(&path, &md, None).expect("build");

        let observed = sacd
            .active_surface()
            .entries
            .iter()
            .map(|entry| entry.display_key.as_str())
            .filter(|key| crate::tui::probe::STANDARD_KEY_ORDER.contains(key))
            .collect::<Vec<_>>();
        let expected = crate::tui::probe::STANDARD_KEY_ORDER
            .iter()
            .copied()
            .filter(|key| observed.contains(key))
            .collect::<Vec<_>>();
        assert_eq!(observed, expected);

        let regular_path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("tests/fixtures/silence.flac");
        let regular_entries = crate::tui::probe::read_all_tags_merged(&[regular_path])
            .expect("read regular-file fixture");
        let regular = regular_entries
            .iter()
            .map(|entry| entry.display_key.as_str())
            .filter(|key| crate::tui::probe::STANDARD_KEY_ORDER.contains(key))
            .collect::<Vec<_>>();
        let regular_expected = crate::tui::probe::STANDARD_KEY_ORDER
            .iter()
            .copied()
            .filter(|key| regular.contains(key))
            .collect::<Vec<_>>();
        assert_eq!(regular, regular_expected);

        let shared_keys = crate::tui::probe::STANDARD_KEY_ORDER
            .iter()
            .copied()
            .filter(|key| observed.contains(key) && regular.contains(key))
            .collect::<Vec<_>>();
        let sacd_shared = observed
            .iter()
            .copied()
            .filter(|key| shared_keys.contains(key))
            .collect::<Vec<_>>();
        let regular_shared = regular
            .iter()
            .copied()
            .filter(|key| shared_keys.contains(key))
            .collect::<Vec<_>>();
        assert_eq!(sacd_shared, regular_shared);

        crate::tui::metadata_autonumber::auto_populate(
            &mut sacd,
            crate::tui::metadata_autonumber::AutoPopulateTarget::TrackTotal,
        )
        .expect("SACD TRACKTOTAL auto-populate");
        crate::tui::metadata_autonumber::auto_populate(
            &mut sacd,
            crate::tui::metadata_autonumber::AutoPopulateTarget::DiscNumber,
        )
        .expect("SACD DISCNUMBER auto-populate");
        crate::tui::metadata_autonumber::auto_populate(
            &mut sacd,
            crate::tui::metadata_autonumber::AutoPopulateTarget::DiscTotal,
        )
        .expect("SACD DISCTOTAL auto-populate");
        let values = |key: &str| {
            sacd.active_surface()
                .entries
                .iter()
                .find(|entry| entry.display_key == key)
                .expect(key)
                .per_file_values
                .clone()
        };
        assert_eq!(values("TRACKTOTAL"), vec!["3"; 3]);
        assert_eq!(values("DISCNUMBER"), vec!["1"; 3]);
        assert_eq!(values("DISCTOTAL"), vec!["1"; 3]);
    }

    #[test]
    fn build_sacd_editor_state_album_level_fields_extracted() {
        let md = synth_sacd_metadata(
            Some("Kind of Blue"),
            Some("Miles Davis"),
            1959,
            Some("PROC-001"),
            &["So What", "Freddie Freeloader"],
            &["Miles Davis Sextet", "Miles Davis Sextet"],
            &[None, None],
        );
        let path = std::path::PathBuf::from("/tmp/test.iso");
        let (state, label, n) = build_sacd_editor_state(&path, &md, None).expect("build");
        assert_eq!(label, "stereo");
        assert_eq!(n, 2);
        // Phase A: with no sidecar present but a writable parent dir,
        // the editor unlocks for the mint-on-save path. `/tmp` is
        // writable in the test environment, so `read_only` flips off
        // and `sacd_sidecar_path` points at the expected target file.
        assert!(!state.read_only);
        assert_eq!(
            state.sacd_sidecar_path.as_deref(),
            Some(std::path::Path::new("/tmp/test.xml")),
        );
        assert_eq!(state.active_surface().paths.len(), 2);
        assert!(state.active_surface().paths.iter().all(|p| p == &path));

        let by_key = |k: &str| state.active_surface().entries.iter().find(|e| e.display_key == k);
        assert_eq!(
            by_key("ALBUM").map(|e| e.value.as_str()),
            Some("Kind of Blue")
        );
        assert_eq!(
            by_key("ALBUMARTIST").map(|e| e.value.as_str()),
            Some("Miles Davis")
        );
        assert_eq!(by_key("DATE").map(|e| e.value.as_str()), Some("1959"));
        assert_eq!(
            by_key("CATALOGNUMBER").map(|e| e.value.as_str()),
            Some("PROC-001")
        );
        assert_eq!(by_key("GENRE").map(|e| e.value.as_str()), Some("Jazz"));
        // Album-level entries share one value across all tracks.
        for k in &["ALBUM", "ALBUMARTIST", "DATE", "CATALOGNUMBER", "GENRE"] {
            let e = by_key(k).expect(k);
            assert_eq!(e.per_file_values.len(), 2);
            assert!(!e.is_mixed);
        }
    }

