    #[test]
    fn sacd_editor_build_edit_save_preserves_per_track_composer_scope() {
        let xml = r#"<root><store id="X" type="SACD" version="1.1">
<track id="1"><meta name="TITLE" value="A"/><meta name="COMPOSER" value="Composer 1"/><meta name="TRACKNUMBER" value="01"/><meta name="TOTALTRACKS" value="3"/></track>
<track id="2"><meta name="TITLE" value="B"/><meta name="COMPOSER" value="Composer 2"/><meta name="TRACKNUMBER" value="02"/><meta name="TOTALTRACKS" value="3"/></track>
<track id="3"><meta name="TITLE" value="C"/><meta name="COMPOSER" value="Composer 3"/><meta name="TRACKNUMBER" value="03"/><meta name="TOTALTRACKS" value="3"/></track>
</store></root>"#;
        let (_td, reparsed) = round_trip_save(xml, |state| {
            let composer = state
                .active_surface_mut()
                .entries
                .iter_mut()
                .find(|entry| entry.display_key.eq_ignore_ascii_case("COMPOSER"))
                .expect("SACD COMPOSER row");
            assert_eq!(composer.row_scope, crate::tui::probe::RowScope::Track);
            assert_eq!(
                composer.per_file_values,
                vec![
                    "Composer 1".to_string(),
                    "Composer 2".to_string(),
                    "Composer 3".to_string(),
                ],
            );
            composer.per_file_values[1].replace_scalar("Edited SACD Composer".to_string());
            composer.value = "<multiple values>".to_string();
            composer.is_mixed = true;
        });
        let by_tid = |tid: u32| {
            reparsed
                .tracks
                .iter()
                .find(|track| track.id == tid)
                .and_then(|track| track.meta.get("COMPOSER"))
                .map(String::as_str)
        };
        assert_eq!(by_tid(1), Some("Composer 1"));
        assert_eq!(by_tid(2), Some("Edited SACD Composer"));
        assert_eq!(by_tid(3), Some("Composer 3"));
    }

    #[test]
    fn save_sacd_sidecar_empty_value_removes_meta_key() {
        let _coordination = crate::concurrency::scoped_test_coordination_root();
        // Clearing a tag in the editor should remove the meta entry
        // from the sidecar entirely, not leave value="" sitting there.
        let xml = r#"<root><store id="X" type="SACD" version="1.1">
<track id="1"><meta name="TITLE" value="A"/><meta name="ARTIST" value="X"/><meta name="TRACKNUMBER" value="01"/><meta name="TOTALTRACKS" value="1"/></track>
</store></root>"#;
        let td = tempfile::tempdir().unwrap();
        let xml_path = td.path().join("disc.xml");
        std::fs::write(&xml_path, xml).unwrap();
        let md = synth_sacd_metadata(None, None, 0, None, &["sb1"], &["sb-perf"], &[None]);
        let sidecar = crate::tui::sacd_sidecar::parse_sidecar(&xml_path).unwrap();
        let iso_path = td.path().join("disc.iso");
        std::fs::write(&iso_path, b"\0").unwrap();
        let (mut state, _, _) = build_sacd_editor_state(&iso_path, &md, Some(&sidecar)).unwrap();
        state.read_only = false;
        state.sacd_sidecar_path = Some(xml_path.clone());
        state.active_surface_mut().sacd_area_kind = Some(crate::tui::sacd::AreaKind::Stereo);

        for entry in state.active_surface_mut().entries.iter_mut() {
            if entry.display_key == "ARTIST" {
                entry.per_file_values = crate::tui::probe::metadata_field_values_from_scalars(vec!["".into()]);
                entry.value = "".into();
                entry.is_mixed = false;
            }
        }

        save_sacd_sidecar(&state, &xml_path).expect("save");
        let reparsed = crate::tui::sacd_sidecar::parse_sidecar(&xml_path).unwrap();
        let t1 = reparsed.tracks.iter().find(|t| t.id == 1).unwrap();
        assert!(!t1.meta.contains_key("ARTIST"), "ARTIST should be removed");
        assert_eq!(
            t1.meta.get("TITLE").map(String::as_str),
            Some("A"),
            "TITLE should still be present"
        );
    }

