    fn channel() -> (mpsc::Sender<AppMessage>, mpsc::Receiver<AppMessage>) {
        mpsc::channel(8)
    }

    fn editor_for_audio_path(path: PathBuf) -> Box<MetadataEditorState> {
        let label = path
            .file_name()
            .map(|name| name.to_string_lossy().into_owned())
            .unwrap_or_else(|| "track.flac".to_string());
        let mut state = Box::new(MetadataEditorState::for_files(
            vec![path],
            Vec::new(),
            vec![label],
            MetadataTechnicalDetails::default(),
        ));
        state.content_tab = ContentTab::Artwork;
        state
    }

    fn make_editor_fixture(dir: &Path) -> Box<MetadataEditorState> {
        let audio_path = dir.join("track.flac");
        fs::write(&audio_path, b"audio").expect("audio fixture");
        editor_for_audio_path(audio_path)
    }

    #[test]
    fn ignored_directory_disclosure_suffix_reaches_the_status_line() {
        // End-to-end pin: the "(N directories ignored)" suffix must survive
        // handle_message (appended AFTER the reducer sets its own status) —
        // but ONLY for completions the reducer actually consumed (round-9
        // consumed-flag gating): stale completions get NO suffix.
        let temp = tempfile::tempdir().expect("picker tempdir");
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let (tx, _rx) = channel();
        let purpose = FilePickerPurpose::Generic {
            id: "suffix-pin".to_string(),
        };
        let session = super::super::app::MetadataFilePickerState::new(
            purpose.clone(),
            tui_file_picker::FilePickerState::new(tui_file_picker::FilePickerConfig {
                start_dir: temp.path().to_path_buf(),
                ..tui_file_picker::FilePickerConfig::default()
            }),
        );
        let session_id = session.session_id;
        app.active_overlay = super::super::app::ActiveOverlay::FilePicker(session);
        super::super::event_loop::handle_message(
            &mut app,
            AppMessage::FilePickerComplete {
                session_id,
                purpose: purpose.clone(),
                path: Some(PathBuf::from("/music/01.flac")),
                paths: vec![PathBuf::from("/music/01.flac")],
                ignored_directories: 2,
            },
            &tx,
        );
        let status = app
            .status_message
            .as_ref()
            .map(|(status, _)| status.clone())
            .expect("consumed completion must set a status");
        assert!(
            status.contains("(2 directories ignored)"),
            "status must carry the disclosure suffix, got: {status}"
        );

        // Stale arm: no matching session anymore — the reducer discards the
        // completion and the suffix must NOT be appended.
        super::super::event_loop::handle_message(
            &mut app,
            AppMessage::FilePickerComplete {
                session_id: session_id + 1,
                purpose,
                path: Some(PathBuf::from("/music/02.flac")),
                paths: vec![PathBuf::from("/music/02.flac")],
                ignored_directories: 3,
            },
            &tx,
        );
        let stale_status = app
            .status_message
            .as_ref()
            .map(|(status, _)| status.clone())
            .expect("stale completion must set a status");
        assert!(
            stale_status.contains("ignored stale completion"),
            "stale completion must be discarded, got: {stale_status}"
        );
        assert!(
            !stale_status.contains("directories ignored"),
            "stale completion must NOT carry the disclosure suffix, got: {stale_status}"
        );
    }

    #[test]
    fn all_non_transfer_picker_purposes_keep_first_path_compatibility() {
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        let (tx, mut rx) = channel();
        let first = PathBuf::from("/music/01.flac");
        let second = PathBuf::from("/music/02.flac");
        let purposes = vec![
            FilePickerPurpose::SelectArtwork {
                picture_type: lofty::picture::PictureType::CoverFront,
            },
            FilePickerPurpose::SelectFile,
            FilePickerPurpose::SelectDirectory,
            FilePickerPurpose::SelectDestination,
            FilePickerPurpose::SelectPreset,
            FilePickerPurpose::SavePreset,
            FilePickerPurpose::CopyTo {
                sources: vec![PathBuf::from("/source/copy.flac")],
                force: false,
            },
            FilePickerPurpose::MoveTo {
                sources: vec![PathBuf::from("/source/move.flac")],
                force: true,
            },
            FilePickerPurpose::MetadataTagBlocksFile,
            FilePickerPurpose::Generic {
                id: "compatibility-pin".to_string(),
            },
        ];

        for (index, purpose) in purposes.into_iter().enumerate() {
            let session_id = index as u64 + 1;
            send_file_picker_completion(
                &mut app,
                &tx,
                session_id,
                purpose.clone(),
                2,
                tui_file_picker::FilePickerAction::SelectedMany(vec![
                    first.clone(),
                    second.clone(),
                ]),
            )
            .expect("queue compatibility completion");

            match rx.try_recv().expect("compatibility completion") {
                AppMessage::FilePickerComplete {
                    session_id: observed_session,
                    purpose: observed_purpose,
                    path,
                    paths,
                    ignored_directories,
                } => {
                    assert_eq!(observed_session, session_id);
                    assert_eq!(observed_purpose, purpose);
                    assert_eq!(path, Some(first.clone()));
                    assert_eq!(paths, vec![first.clone(), second.clone()]);
                    assert_eq!(ignored_directories, 2);
                }
                other => panic!("expected FilePickerComplete, got {other:?}"),
            }
        }
    }

