        let surface = state.active_surface();

        let isrc = surface
            .entries
            .iter()
            .find(|entry| entry.display_key.eq_ignore_ascii_case("ISRC"))
            .expect("ISRC row");
        assert_eq!(isrc.per_file_values.len(), 10, "ISRC must be row-dimensioned");
        assert_eq!(isrc.per_file_values[0], "GBAYE0300301");
