    #[test]
    fn creatable_sidecar_is_fallback_and_never_displaces_present_metadata() {
        use crate::config::AggregateMetadataTarget::{
            EmbeddedCue, IndividualFiles, SidecarCue,
        };
        let mut embedded_surface = policy_surface();
        embedded_surface.cue_path = embedded_surface.audio_path.clone();
        let embedded = ResolvedEmbeddedMetadataSurface {
            surface: embedded_surface.clone(),
            multi_file_read_only: false,
        };
        let paths = vec![embedded_surface.audio_path.clone()];

        // The directory resolver receives no create-only sidecar authority.
        // Even with SidecarCue first in configured priority, the absent sidecar
        // cannot displace the embedded representation that is actually present.
        let embedded_present = resolve_directory_metadata_groups(
            &paths,
            &[],
            vec![embedded],
            &[SidecarCue, EmbeddedCue, IndividualFiles],
            &std::collections::BTreeSet::new(),
            |_| Ok(None),
            "metadata test",
        )
        .expect("present embedded source must remain authoritative");
        assert_eq!(embedded_present.len(), 1);
        assert_eq!(embedded_present[0].representation, EmbeddedCue);
        assert_eq!(
            embedded_present[0].selected_surfaces[0].cue_path,
            embedded_surface.audio_path
        );
    }

    fn embedded_candidate() -> EmbeddedCueCandidate {
        let cue_text = concat!(
            "PERFORMER \"Embedded Artist\"\n",
            "TITLE \"Embedded Album\"\n",
            "FILE \"album.flac\" FLAC\n",
            "  TRACK 01 AUDIO\n    INDEX 01 00:00:00\n",
            "  TRACK 02 AUDIO\n    INDEX 01 03:00:00\n",
        )
        .to_string();
        EmbeddedCueCandidate::Valid {
            audio_path: std::path::PathBuf::from("/album/album.flac"),
            sheet: crate::tui::cue_parser::parse_cue(&cue_text),
            cue_text,
            multi_file_read_only: false,
        }
    }

    fn policy_surface_with_catalog(catalog: Option<&str>) -> MetadataCueSurface {
        let catalog_line = catalog
            .map(|value| format!("CATALOG {value}\n"))
            .unwrap_or_default();
        let cue_text = format!(
            "PERFORMER \"Sidecar Artist\"\nTITLE \"Sidecar Album\"\n{catalog_line}FILE \"album.flac\" FLAC\n  TRACK 01 AUDIO\n    INDEX 01 00:00:00\n  TRACK 02 AUDIO\n    INDEX 01 03:00:00\n"
        );
        MetadataCueSurface {
            cue_path: std::path::PathBuf::from("/album/album.cue"),
            audio_path: std::path::PathBuf::from("/album/album.flac"),
            audio_paths: vec![std::path::PathBuf::from("/album/album.flac")],
            track_audio_paths: vec![
                std::path::PathBuf::from("/album/album.flac"),
                std::path::PathBuf::from("/album/album.flac"),
            ],
            role: crate::convert::split_cue_album::SplitCueMemberRole::SyntheticAlbumPart,
            sheet: crate::tui::cue_parser::parse_cue(&cue_text),
            cue_text,
        }
    }

    #[test]
    fn selected_sidecar_catalognumber_is_unique_idempotent_and_survives_album_edit() {
        let surface = policy_surface_with_catalog(Some("25AP-1115"));
        let mut entries = Vec::new();
        apply_policy_selected_metadata_cue_source(
            &mut entries,
            &surface,
            crate::convert::pipeline::CueSidecarPolicy::SidecarOnly,
        )
        .expect("selected sidecar source");

        let catalog_entry = entries
            .iter()
            .find(|entry| entry.display_key.eq_ignore_ascii_case("CATALOGNUMBER"))
            .expect("nonempty selected CUE CATALOG must surface");
        assert_eq!(catalog_entry.value, "25AP-1115");

        entries.push(catalog_entry.clone());
        apply_policy_selected_metadata_cue_source(
            &mut entries,
            &surface,
            crate::convert::pipeline::CueSidecarPolicy::SidecarOnly,
        )
        .expect("repeated selected sidecar source");
        assert_eq!(
            entries
                .iter()
                .filter(|entry| entry.display_key.eq_ignore_ascii_case("CATALOGNUMBER"))
                .count(),
            1,
            "repeated construction must collapse equivalent catalog rows"
        );

        cue_album_upsert_album_entry(
            &mut entries,
            "ALBUM",
            lofty::tag::ItemKey::AlbumTitle,
            Some("Edited Album".to_string()),
            1,
        );
        assert_eq!(
            entries
                .iter()
                .filter(|entry| entry.display_key.eq_ignore_ascii_case("CATALOGNUMBER"))
                .count(),
            1,
            "editing ALBUM must not remove the selected CUE catalog row"
        );
    }

