    #[test]
    fn transfer_structural_admission_never_performs_ordinary_directory_expansion() {
        let temp = tempfile::tempdir().expect("tempdir");
        let cue_less = temp.path().join("cue-less");
        std::fs::create_dir_all(cue_less.join("nested")).expect("cue-less tree");
        std::fs::write(cue_less.join("nested/track.flac"), b"audio").expect("audio");

        let rejected = temp.path().join("rejected");
        std::fs::create_dir_all(&rejected).expect("rejected tree");
        std::fs::write(rejected.join("track.flac"), b"audio").expect("audio");
        std::fs::write(
            rejected.join("broken.cue"),
            concat!(
                "FILE \"missing.flac\" WAVE\n",
                "  TRACK 01 AUDIO\n",
                "    INDEX 01 00:00:00\n",
                "  TRACK 02 AUDIO\n",
                "    INDEX 01 03:00:00\n",
            ),
        )
        .expect("rejected cue");

        for root in [cue_less, rejected] {
            let admission = collect_transfer_metadata_cue_admission(&[root]);
            assert!(
                admission.ordinary_paths.is_empty(),
                "transfer admission is structural only; bounded traversal owns ordinary expansion"
            );
        }
    }

    #[test]
    fn transfer_directory_fallback_enforces_caps_for_cueless_and_rejected_cues() {
        let temp = tempfile::tempdir().expect("tempdir");
        let cue_less = temp.path().join("cue-less");
        let rejected = temp.path().join("rejected");
        std::fs::create_dir_all(&cue_less).expect("cue-less directory");
        std::fs::create_dir_all(&rejected).expect("rejected directory");
        for index in 0..4 {
            std::fs::write(cue_less.join(format!("{index}.flac")), b"audio")
                .expect("cue-less audio");
            std::fs::write(rejected.join(format!("{index}.flac")), b"audio")
                .expect("rejected audio");
        }
        std::fs::write(
            rejected.join("broken.cue"),
            concat!(
                "FILE \"missing.flac\" WAVE\n",
                "  TRACK 01 AUDIO\n",
                "    INDEX 01 00:00:00\n",
                "  TRACK 02 AUDIO\n",
                "    INDEX 01 03:00:00\n",
            ),
        )
        .expect("rejected cue");

        let cancel = crate::tui::probe::MetadataWriteCancelFlag::new();
        for root in [&cue_less, &rejected] {
            let visit_error = classify_tag_transfer_roots_with_default_priority_and_limits_for_test(
                &[root.clone()],
                &cancel,
                TransferTraversalLimits {
                    max_visited: 2,
                    max_audio_files: 32,
                },
            )
            .expect_err("visitation cap must stop the bounded transfer traversal");
            assert!(visit_error.contains(
                "Transfer tags refused: selection traversal exceeds 2 filesystem entries"
            ));

            let file_error = classify_tag_transfer_roots_with_default_priority_and_limits_for_test(
                &[root.clone()],
                &cancel,
                TransferTraversalLimits {
                    max_visited: 64,
                    max_audio_files: 2,
                },
            )
            .expect_err("audio-file cap must stop the bounded transfer traversal");
            assert!(file_error.contains(
                "Transfer tags refused: selection exceeds 2 audio files"
            ));
        }
    }

    #[test]
    fn transfer_directory_fallback_observes_cancellation_during_bounded_walk() {
        let temp = tempfile::tempdir().expect("tempdir");
        let root = temp.path().join("album");
        std::fs::create_dir_all(&root).expect("directory");
        for index in 0..8 {
            std::fs::write(root.join(format!("{index}.flac")), b"audio").expect("audio");
        }
        let checks = std::cell::Cell::new(0usize);
        let error = super::super::command::expand_audio_paths_for_transfer_limited(
            &[root],
            64,
            64,
            || {
                let next = checks.get() + 1;
                checks.set(next);
                next >= 4
            },
        )
        .expect_err("cancellation must stop traversal");
        assert_eq!(
            error,
            "Transfer tags cancelled during bounded directory traversal"
        );
        assert!(checks.get() >= 4);
    }

    // Multiple explicitly-selected audio files remain an explicit `Files`
    // representation and short-circuit before sidecar discovery or embedded-CUE
    // probing. Single-file explicit selections intentionally do not use this
    // bypass: they share aggregate viability with directory classification.
    #[test]
    fn explicit_taggable_multi_file_selection_writes_files_without_folder_admission() {
        TRANSFER_CLASSIFICATION_ADMISSION_PASSES.with(|count| count.set(0));
        TRANSFER_CLASSIFICATION_EMBEDDED_BATCH_READS.with(|count| count.set(0));

        let temp = tempfile::tempdir().expect("tempdir");
        let first = temp.path().join("01.flac");
        let second = temp.path().join("02.flac");
        std::fs::write(&first, b"not a real FLAC").expect("first fixture");
        std::fs::write(&second, b"not a real FLAC").expect("second fixture");
        let cancel = crate::tui::probe::MetadataWriteCancelFlag::new();
        let carrier = classify_tag_transfer_roots_with_default_priority_for_test(
            &[first.clone(), second.clone()],
            &cancel,
        )
        .expect("taggable multi-file selection classifies");

        match carrier {
            super::super::tag_interchange::TransferCarrier::Files { paths } => {
                assert_eq!(paths, vec![first, second], "both selected files are the transfer targets");
            }
            other => panic!("explicit taggable multi-file selection must yield a Files carrier, got {other:?}"),
        }
        assert_eq!(
            TRANSFER_CLASSIFICATION_ADMISSION_PASSES.with(|count| count.get()),
            0,
            "taggable explicit selection must short-circuit before folder-admission",
        );
        assert_eq!(
            TRANSFER_CLASSIFICATION_EMBEDDED_BATCH_READS.with(|count| count.get()),
            0,
            "Files path defers tag reads to transfer time; no classification-time read",
        );
    }

    #[test]
    fn explicit_cue_classification_accepts_role_aware_multi_file_and_refuses_invalid_mixed_selections() {
        let temp = tempfile::tempdir().expect("tempdir");
        let album = temp.path();
        let image_a = album.join("a.flac");
        let image_b = album.join("b.flac");
        std::fs::write(&image_a, b"placeholder").expect("image a");
        std::fs::write(&image_b, b"placeholder").expect("image b");

        let valid = album.join("valid.cue");
        std::fs::write(
            &valid,
            r#"FILE "a.flac" WAVE
  TRACK 01 AUDIO
    INDEX 01 00:00:00
  TRACK 02 AUDIO
    INDEX 01 03:00:00
"#,
        )
        .expect("valid cue");
        let cancel = crate::tui::probe::MetadataWriteCancelFlag::new();
        let carrier = classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&valid), &cancel)
            .expect("explicit cue carrier");
        assert!(matches!(
            carrier,
            super::super::tag_interchange::TransferCarrier::SidecarCue { ref cue_path, .. }
                if cue_path == &valid
        ));

        let missing = album.join("missing.cue");
        std::fs::write(
            &missing,
            r#"FILE "missing.flac" WAVE
  TRACK 01 AUDIO
    INDEX 01 00:00:00
  TRACK 02 AUDIO
    INDEX 01 03:00:00
"#,
        )
        .expect("missing cue");
        assert!(classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&missing), &cancel)
            .expect_err("missing FILE reference must refuse")
            .contains("admission failed"));

        let one_track = album.join("one-track.cue");
        std::fs::write(
            &one_track,
            r#"FILE "a.flac" WAVE
  TRACK 01 AUDIO
    INDEX 01 00:00:00
"#,
        )
        .expect("one-track cue");
        assert!(classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&one_track), &cancel)
            .expect_err("one-track cue must refuse")
            .contains("fewer than 2"));

        let multi_file = album.join("multi-file.cue");
        std::fs::write(
            &multi_file,
            r#"FILE "b.flac" WAVE
  TRACK 02 AUDIO
    INDEX 01 00:00:00
FILE "a.flac" WAVE
  TRACK 01 AUDIO
    INDEX 01 00:00:00
"#,
        )
        .expect("multi-file cue");
        let multi_file_carrier =
            classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&multi_file), &cancel)
                .expect("multi-file explicit CUE carrier");
        let super::super::tag_interchange::TransferCarrier::SidecarCue {
            cue_path,
            image_paths,
            track_audio_paths,
            role,
            write_method,
            ..
        } = multi_file_carrier
        else {
            panic!("multi-file explicit CUE must remain a sidecar carrier");
        };
        assert_eq!(cue_path, multi_file);
        assert_eq!(image_paths, vec![image_b.clone(), image_a.clone()]);
        assert_eq!(track_audio_paths, vec![image_a.clone(), image_b.clone()]);
        assert_eq!(
            role,
            crate::convert::split_cue_album::SplitCueMemberRole::MetadataSidecar
        );
        assert_eq!(
            write_method,
            super::super::tag_interchange::SidecarCueWriteMethod::SidecarOnly
        );

        assert!(classify_tag_transfer_roots_with_default_priority_for_test(&[valid, image_b], &cancel)
            .expect_err("mixed cue and audio must refuse")
            .contains("selection mixes a CUE with audio files"));

        let archive = album.join("album.zip");
        std::fs::write(&archive, b"archive").expect("archive");
        assert!(classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&archive), &cancel)
            .expect_err("archive must refuse")
            .contains("archives"));

        let ambiguous = album.join("ambiguous");
        std::fs::create_dir_all(&ambiguous).expect("ambiguous folder");
        for stem in ["one", "two"] {
            std::fs::write(ambiguous.join(format!("{stem}.flac")), b"placeholder")
                .expect("ambiguous image");
            std::fs::write(
                ambiguous.join(format!("{stem}.cue")),
                format!(
                    "FILE \"{stem}.flac\" WAVE\n  TRACK 01 AUDIO\n    INDEX 01 00:00:00\n  TRACK 02 AUDIO\n    INDEX 01 03:00:00\n"
                ),
            )
            .expect("ambiguous cue");
        }
        assert!(classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&ambiguous), &cancel)
            .expect_err("multiple CUE scopes must refuse")
            .contains("multiple CUE albums"));
        let files_first_ambiguous = classify_tag_transfer_roots(
            std::slice::from_ref(&ambiguous),
            &[
                crate::config::AggregateMetadataTarget::IndividualFiles,
                crate::config::AggregateMetadataTarget::SidecarCue,
                crate::config::AggregateMetadataTarget::EmbeddedCue,
            ],
            &cancel,
        )
        .expect("files-first directory policy bypasses irrelevant CUE ambiguity");
        assert!(matches!(
            files_first_ambiguous,
            super::super::tag_interchange::TransferCarrier::Files { paths }
                if paths.len() == 2
        ));

        let empty = album.join("empty");
        std::fs::create_dir(&empty).expect("empty folder");
        assert!(classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&empty), &cancel)
            .expect_err("empty folder must refuse")
            .contains("contains no audio files"));

        use std::io::{Seek, SeekFrom, Write};
        let disc = album.join("disc.iso");
        let total = (crate::tui::sacd::MASTER_TOC_LSNS[0] + 1)
            * crate::tui::sacd::SECTOR_SIZE;
        let mut iso = std::fs::File::create(&disc).expect("SACD fixture");
        iso.set_len(total).expect("size SACD fixture");
        iso.seek(SeekFrom::Start(
            crate::tui::sacd::MASTER_TOC_LSNS[0] * crate::tui::sacd::SECTOR_SIZE,
        ))
        .expect("seek SACD fixture");
        iso.write_all(crate::tui::sacd::MASTER_TOC_MAGIC)
            .expect("write SACD magic");
        drop(iso);
        assert!(classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&disc), &cancel)
            .expect_err("disc image must refuse")
            .contains("disc-image"));
    }

    #[test]
    fn metadata_completion_sources_cover_requested_fields() {
        let field_names = metadata_field_name_completion_candidates();
        assert!(field_names.iter().any(|candidate| candidate == "DISCOGS_URL"));
        assert!(field_names.iter().any(|candidate| candidate == "LINEAGE"));

        for field in [
            "ARTIST",
            "ALBUMARTIST",
            "GENRE",
            "PERFORMER",
            "COUNTRY",
            "COMPOSER",
        ] {
            assert!(
                metadata_value_completion_candidates(field).is_some(),
                "missing completion source for {field}",
            );
        }
        assert!(metadata_value_completion_candidates("LINEAGE").is_none());
    }

    #[test]
    fn configured_tag_transfer_entry_uses_live_priority_for_directory_and_explicit_image() {
        let temp = tempfile::tempdir().expect("tempdir");
        let album = temp.path().join("album");
        std::fs::create_dir_all(&album).expect("album");
        let image = album.join("album.flac");
        let cue = album.join("album.cue");
        assert!(create_flac_fixture(&image), "flac fixture");
        let sidecar = concat!(
            "TITLE \"Sidecar Album\"\n",
            "FILE \"album.flac\" WAVE\n",
            "  TRACK 01 AUDIO\n",
            "    TITLE \"One\"\n",
            "    INDEX 01 00:00:00\n",
            "  TRACK 02 AUDIO\n",
            "    TITLE \"Two\"\n",
            "    INDEX 01 00:30:00\n",
        );
        let embedded = sidecar.replace("Sidecar Album", "Embedded Album");
        std::fs::write(&cue, sidecar).expect("sidecar cue");
        crate::tui::probe::write_all_tags(
            &image,
            &[
                (
                    lofty::tag::ItemKey::Unknown("CUESHEET".to_string()),
                    Some(embedded.clone()),
                ),
                (
                    lofty::tag::ItemKey::Genre,
                    Some("File Genre".to_string()),
                ),
            ],
        )
        .expect("embedded cuesheet");

        use crate::config::AggregateMetadataTarget::{
            EmbeddedCue, IndividualFiles, SidecarCue,
        };
        let cancel = crate::tui::probe::MetadataWriteCancelFlag::new();
        let mut app = AppState::new_for_test(TonepoetConfig::default());
        app.config.conversion.aggregate_metadata_target_priority =
            vec![SidecarCue, EmbeddedCue, IndividualFiles];
        let by_directory = classify_tag_transfer_roots(
            std::slice::from_ref(&album),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("sidecar-first directory carrier");
        let by_cue = classify_tag_transfer_roots(
            std::slice::from_ref(&cue),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("explicit cue carrier");
        let by_image_with_embedded = classify_tag_transfer_roots(
            std::slice::from_ref(&image),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("explicit image carrier");

        for carrier in [&by_directory, &by_cue] {
            assert!(matches!(
                carrier,
                super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                    if cue_path == &cue
            ));
        }
        assert!(matches!(
            &by_image_with_embedded,
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                if cue_path == &cue
        ));
        assert_eq!(
            transfer_entry_values(&by_image_with_embedded, "ALBUM"),
            vec!["Sidecar Album".to_string(), "Sidecar Album".to_string()],
            "explicit and directory classification must select the same viable sidecar under sidecar-first priority",
        );

        app.config.conversion.aggregate_metadata_target_priority =
            vec![IndividualFiles, SidecarCue, EmbeddedCue];
        let files_first = classify_tag_transfer_roots(
            std::slice::from_ref(&album),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("individual-first skips a nonviable single-image representation");
        assert!(matches!(
            &files_first,
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                if cue_path == &cue
        ));
        assert_eq!(
            transfer_entry_values(&files_first, "ALBUM"),
            vec!["Sidecar Album".to_string(), "Sidecar Album".to_string()],
            "the observable source rows must come from the selected sidecar"
        );
        assert_eq!(
            transfer_entry_values(&files_first, "GENRE"),
            vec!["File Genre".to_string(), "File Genre".to_string()],
            "fields omitted by an image-backed sidecar must retain their file-tag fallback"
        );

        app.config.conversion.aggregate_metadata_target_priority =
            vec![EmbeddedCue, SidecarCue, IndividualFiles];
        let embedded_first = classify_tag_transfer_roots(
            std::slice::from_ref(&album),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("embedded-first directory carrier");
        assert!(matches!(
            &embedded_first,
            super::super::tag_interchange::TransferCarrier::EmbeddedCue {
                image_path,
                ..
            } if image_path == &image
        ));
        assert_eq!(
            transfer_entry_values(&embedded_first, "ALBUM"),
            vec!["Embedded Album".to_string(), "Embedded Album".to_string()],
            "the observable source rows must come from the selected embedded CUE"
        );
        let explicit_embedded_first = classify_tag_transfer_roots(
            std::slice::from_ref(&image),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("embedded-first explicit image carrier");
        assert!(matches!(
            &explicit_embedded_first,
            super::super::tag_interchange::TransferCarrier::EmbeddedCue { image_path, .. }
                if image_path == &image
        ));
        assert_eq!(
            transfer_entry_values(&explicit_embedded_first, "ALBUM"),
            vec!["Embedded Album".to_string(), "Embedded Album".to_string()],
        );

        let one_track_embedded = concat!(
            "TITLE \"One-track embedded\"\n",
            "FILE \"album.flac\" WAVE\n",
            "  TRACK 01 AUDIO\n",
            "    TITLE \"Only\"\n",
            "    INDEX 01 00:00:00\n",
        );
        crate::tui::probe::write_all_tags(
            &image,
            &[(
                lofty::tag::ItemKey::Unknown("CUESHEET".to_string()),
                Some(one_track_embedded.to_string()),
            )],
        )
        .expect("write one-track embedded cue");
        let one_track_falls_through = classify_tag_transfer_roots(
            std::slice::from_ref(&image),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("one-track embedded cue falls through to sidecar");
        assert!(matches!(
            one_track_falls_through,
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                if cue_path == cue
        ));
        crate::tui::probe::write_all_tags(
            &image,
            &[(
                lofty::tag::ItemKey::Unknown("CUESHEET".to_string()),
                Some(embedded.clone()),
            )],
        )
        .expect("restore two-track embedded cue");

        app.config.conversion.aggregate_metadata_target_priority =
            vec![IndividualFiles, EmbeddedCue, SidecarCue];
        let explicit_cue_with_files_first = classify_tag_transfer_roots(
            std::slice::from_ref(&cue),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("explicit CUE bypasses directory policy");
        assert!(matches!(
            explicit_cue_with_files_first,
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                if cue_path == cue
        ));
        app.config.conversion.aggregate_metadata_target_priority =
            vec![IndividualFiles, SidecarCue, EmbeddedCue];
        let explicit_image_with_files_first = classify_tag_transfer_roots(
            std::slice::from_ref(&image),
            &app.config.conversion.aggregate_metadata_target_priority,
            &cancel,
        )
        .expect("explicit image applies viability before configured priority");
        assert!(matches!(
            explicit_image_with_files_first,
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                if cue_path == cue
        ));

        crate::tui::probe::write_all_tags(
            &image,
            &[(lofty::tag::ItemKey::Unknown("CUESHEET".to_string()), None)],
        )
        .expect("remove embedded cuesheet");
        let by_image_without_embedded =
            classify_tag_transfer_roots_with_default_priority_for_test(std::slice::from_ref(&image), &cancel)
                .expect("sidecar fallback carrier");
        assert!(matches!(
            by_image_without_embedded,
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path, .. }
                if cue_path == cue
        ));
    }

    #[test]
    fn mixed_folder_resolves_each_independent_album_group_before_aggregation() {
        if !fixture_tool_available("ffmpeg") {
            eprintln!("skipping: ffmpeg unavailable");
            return;
        }
        use crate::config::AggregateMetadataTarget::{
            EmbeddedCue, IndividualFiles, SidecarCue,
        };
        let temp = tempfile::tempdir().expect("tempdir");
        let album = temp.path().join("mixed-albums");
        std::fs::create_dir_all(&album).expect("album dir");
        let sidecar_image = album.join("z-sidecar.flac");
        let embedded_image = album.join("a-embedded.flac");
        let cue_path = album.join("z-sidecar.cue");
        assert!(create_flac_fixture(&sidecar_image), "sidecar image fixture");
        assert!(create_flac_fixture(&embedded_image), "embedded image fixture");
        std::fs::write(
            &cue_path,
            concat!(
                "TITLE \"Sidecar Album\"\n",
                "FILE \"z-sidecar.flac\" FLAC\n",
                "  TRACK 01 AUDIO\n    TITLE \"Sidecar One\"\n    INDEX 01 00:00:00\n",
                "  TRACK 02 AUDIO\n    TITLE \"Sidecar Two\"\n    INDEX 01 00:30:00\n",
            ),
        )
        .expect("sidecar fixture");
        let embedded = concat!(
            "TITLE \"Embedded Album\"\n",
            "FILE \"a-embedded.flac\" FLAC\n",
            "  TRACK 01 AUDIO\n    TITLE \"Embedded One\"\n    INDEX 01 00:00:00\n",
            "  TRACK 02 AUDIO\n    TITLE \"Embedded Two\"\n    INDEX 01 00:30:00\n",
        );
        crate::tui::probe::write_all_tags(
            &embedded_image,
            &[(
                lofty::tag::ItemKey::Unknown("CUESHEET".to_string()),
                Some(embedded.to_string()),
            )],
        )
        .expect("embedded fixture");

        let cancel = crate::tui::probe::MetadataWriteCancelFlag::new();
        let carrier = classify_tag_transfer_roots(
            std::slice::from_ref(&album),
            &[EmbeddedCue, SidecarCue, IndividualFiles],
            &cancel,
        )
        .expect("mixed folder carrier");
        let super::super::tag_interchange::TransferCarrier::Aggregate { carriers } = &carrier
        else {
            panic!("independent album groups must survive as an aggregate");
        };
        assert_eq!(carriers.len(), 2);
        assert!(matches!(
            &carriers[0],
            super::super::tag_interchange::TransferCarrier::EmbeddedCue { image_path, .. }
                if image_path == &embedded_image
        ));
        assert!(matches!(
            &carriers[1],
            super::super::tag_interchange::TransferCarrier::SidecarCue { cue_path: selected, .. }
                if selected == &cue_path
        ));
        assert_eq!(
            transfer_entry_values(&carrier, "ALBUM"),
            vec![
                "Embedded Album".to_string(),
                "Embedded Album".to_string(),
                "Sidecar Album".to_string(),
                "Sidecar Album".to_string(),
            ],
            "each group must use its own highest-priority viable source and retain directory order"
        );
    }


    #[test]
    fn metadata_editor_resolves_sidecar_and_embedded_album_groups_independently() {
        if !fixture_tool_available("ffmpeg") {
            eprintln!("skipping: ffmpeg unavailable");
            return;
        }
        use crate::config::AggregateMetadataTarget::{
            EmbeddedCue, IndividualFiles, SidecarCue,
        };
        let temp = tempfile::tempdir().expect("tempdir");
        let folder = temp.path().join("mixed-editor-groups");
        std::fs::create_dir_all(&folder).expect("folder");
        let sidecar_image = folder.join("album-a.flac");
        let sidecar_path = folder.join("album-a.cue");
        let embedded_image = folder.join("album-b.flac");
        assert!(create_flac_fixture(&sidecar_image), "sidecar image");
        assert!(create_flac_fixture(&embedded_image), "embedded image");
        std::fs::write(
            &sidecar_path,
            concat!(
                "TITLE \"Sidecar Album\"\n",
                "FILE \"album-a.flac\" FLAC\n",
                "  TRACK 01 AUDIO\n    TITLE \"Sidecar One\"\n    INDEX 01 00:00:00\n",
                "  TRACK 02 AUDIO\n    TITLE \"Sidecar Two\"\n    INDEX 01 00:00:03\n",
            ),
        )
        .expect("sidecar CUE");
        let embedded_text = concat!(
            "TITLE \"Embedded Album\"\n",
            "FILE \"album-b.flac\" FLAC\n",
            "  TRACK 01 AUDIO\n    TITLE \"Embedded One\"\n    INDEX 01 00:00:00\n",
            "  TRACK 02 AUDIO\n    TITLE \"Embedded Two\"\n    INDEX 01 00:00:03\n",
        );
        crate::tui::probe::write_all_tags(
            &embedded_image,
            &[(
                lofty::tag::ItemKey::Unknown("CUESHEET".to_string()),
                Some(embedded_text.to_string()),
            )],
        )
        .expect("embedded CUE");

        let mut config = TonepoetConfig::default();
        config.conversion.aggregate_metadata_target_priority =
            vec![SidecarCue, EmbeddedCue, IndividualFiles];
        let mut app = AppState::new_for_test(config);
        select_foxy_route(&mut app, &folder, temp.path());
        open_metadata_editor(&mut app);
        let ActiveOverlay::MetadataEditor(state) = &app.active_overlay else {
            panic!("mixed folder must open the metadata editor");
        };
        assert_eq!(state.presentation_tabs.len(), 2);
        let sidecar_tab = state
            .presentation_tabs
            .iter()
            .find(|tab| matches!(
                &tab.cue_source,
                Some(crate::tui::app::MetadataCueSource::Sidecar(path))
                    if path == &sidecar_path
            ))
            .expect("sidecar presentation");
        let embedded_tab = state
            .presentation_tabs
            .iter()
            .find(|tab| matches!(
                &tab.cue_source,
                Some(crate::tui::app::MetadataCueSource::Embedded(path))
                    if path == &embedded_image
            ))
            .expect("embedded presentation");
        assert_eq!(sidecar_tab.paths, vec![sidecar_image]);
        assert_eq!(embedded_tab.paths, vec![embedded_image]);
        assert_eq!(
            sidecar_tab
                .entries
                .iter()
                .find(|entry| entry.display_key.eq_ignore_ascii_case("ALBUM"))
                .map(|entry| entry.value.as_str()),
            Some("Sidecar Album")
        );
        assert_eq!(
            embedded_tab
                .entries
                .iter()
                .find(|entry| entry.display_key.eq_ignore_ascii_case("ALBUM"))
                .map(|entry| entry.value.as_str()),
            Some("Embedded Album")
        );
    }

