    #[test]
    fn aggregate_directory_uses_sidecar_but_explicit_members_remain_file_scoped() {
        if !fixture_tool_available("ffmpeg") {
            eprintln!("skipping: ffmpeg unavailable");
            return;
        }
        let temp = tempfile::tempdir().expect("tempdir");
        let album = temp.path().join("album");
        std::fs::create_dir_all(&album).expect("album");
        let first = album.join("01.flac");
        let second = album.join("02.flac");
        let cue = album.join("album.cue");
        assert!(create_flac_fixture(&first), "first member fixture");
        assert!(create_flac_fixture(&second), "second member fixture");
        std::fs::write(
            &cue,
            concat!(
                "FILE \"02.flac\" WAVE\n",
                "  TRACK 02 AUDIO\n",
                "    INDEX 01 00:00:00\n",
                "FILE \"01.flac\" WAVE\n",
                "  TRACK 01 AUDIO\n",
                "    INDEX 01 00:00:00\n",
            ),
        )
        .expect("multi-file cue");

        use crate::config::AggregateMetadataTarget::{
            EmbeddedCue, IndividualFiles, SidecarCue,
        };
        let orders = [
            vec![IndividualFiles, SidecarCue, EmbeddedCue],
            vec![SidecarCue, EmbeddedCue, IndividualFiles],
            vec![EmbeddedCue, SidecarCue, IndividualFiles],
        ];
        let cancel = crate::tui::probe::MetadataWriteCancelFlag::new();

        let by_folder = classify_tag_transfer_roots(
            std::slice::from_ref(&album),
            &[SidecarCue, EmbeddedCue, IndividualFiles],
            &cancel,
        )
        .expect("sidecar-first folder carrier");
        assert!(matches!(
            by_folder,
            super::super::tag_interchange::TransferCarrier::SidecarCue {
                cue_path,
                track_audio_paths,
                role: crate::convert::split_cue_album::SplitCueMemberRole::MetadataSidecar,
                write_method: super::super::tag_interchange::SidecarCueWriteMethod::PerFileAndSidecar,
                ..
            } if cue_path == cue && track_audio_paths == vec![first.clone(), second.clone()]
        ));

        let by_cue = classify_tag_transfer_roots(
            std::slice::from_ref(&cue),
            &[IndividualFiles, EmbeddedCue, SidecarCue],
            &cancel,
        )
        .expect("explicit cue carrier");
        assert!(matches!(
            by_cue,
            super::super::tag_interchange::TransferCarrier::SidecarCue {
                cue_path,
                write_method: super::super::tag_interchange::SidecarCueWriteMethod::SidecarOnly,
                ..
            } if cue_path == cue
        ));

        for order in orders {
            let by_first = classify_tag_transfer_roots(
                std::slice::from_ref(&first),
                &order,
                &cancel,
            )
            .expect("first explicit member");
            assert!(matches!(
                by_first,
                super::super::tag_interchange::TransferCarrier::Files { paths }
                    if paths == vec![first.clone()]
            ));

            let by_second = classify_tag_transfer_roots(
                std::slice::from_ref(&second),
                &order,
                &cancel,
            )
            .expect("second explicit member");
            assert!(matches!(
                by_second,
                super::super::tag_interchange::TransferCarrier::Files { paths }
                    if paths == vec![second.clone()]
            ));

            let by_both = classify_tag_transfer_roots(
                &[second.clone(), first.clone()],
                &order,
                &cancel,
            )
            .expect("multiple explicit members");
            assert!(matches!(
                by_both,
                super::super::tag_interchange::TransferCarrier::Files { paths }
                    if paths == vec![first.clone(), second.clone()]
            ));
        }
    }

    #[test]
    fn cue_source_identity_is_selected_by_cue_sidecar_policy() {
        let surface = policy_surface();
        let embedded = embedded_candidate();

        let sidecar = resolve_metadata_cue_source(
            crate::convert::pipeline::CueSidecarPolicy::PreferSidecar,
            &surface,
            &embedded,
        )
        .expect("prefer sidecar");
        assert!(matches!(
            &sidecar.identity,
            crate::tui::app::MetadataCueSource::Sidecar(path)
                if path == std::path::Path::new("/album/album.cue")
        ));
        assert_eq!(
            sidecar.sheet.title.as_deref(),
            Some("Embedded Album"),
            "sidecar authority should mirror the pipeline's structurally-matched embedded metadata upgrade"
        );

        let embedded_source = resolve_metadata_cue_source(
            crate::convert::pipeline::CueSidecarPolicy::PreferEmbedded,
            &surface,
            &embedded,
        )
        .expect("prefer embedded");
        assert!(matches!(
            &embedded_source.identity,
            crate::tui::app::MetadataCueSource::Embedded(path)
                if path == std::path::Path::new("/album/album.flac")
        ));
        assert_eq!(
            embedded_source.sheet.title.as_deref(),
            Some("Embedded Album")
        );
    }

    #[test]
    fn sidecar_policy_keeps_sidecar_metadata_when_embedded_boundaries_disagree() {
        let surface = policy_surface();
        let mut embedded = embedded_candidate();
        if let EmbeddedCueCandidate::Valid { sheet, .. } = &mut embedded {
            sheet.tracks[1].index01_frames = Some(225 * 75);
        }

        let resolved = resolve_metadata_cue_source(
            crate::convert::pipeline::CueSidecarPolicy::PreferSidecar,
            &surface,
            &embedded,
        )
        .expect("prefer sidecar with mismatched embedded geometry");

        assert!(matches!(
            resolved.identity,
            crate::tui::app::MetadataCueSource::Sidecar(_)
        ));
        assert_eq!(resolved.sheet.title.as_deref(), Some("Sidecar Album"));
    }

    #[test]
    fn cue_policy_fallback_and_required_source_semantics_match_pipeline_policy() {
        let surface = policy_surface();
        let prefer_embedded = resolve_metadata_cue_source(
            crate::convert::pipeline::CueSidecarPolicy::PreferEmbedded,
            &surface,
            &EmbeddedCueCandidate::Absent,
        )
        .expect("PreferEmbedded falls back to sidecar");
        assert!(matches!(
            prefer_embedded.identity,
            crate::tui::app::MetadataCueSource::Sidecar(_)
        ));

        let embedded_only = resolve_metadata_cue_source(
            crate::convert::pipeline::CueSidecarPolicy::EmbeddedOnly,
            &surface,
            &EmbeddedCueCandidate::Absent,
        )
        .expect_err("EmbeddedOnly must fail without an embedded CUESHEET");
        assert!(embedded_only.contains("requires an embedded CUESHEET"));

        let invalid = EmbeddedCueCandidate::Invalid("duplicate track number".to_string());
        let prefer_invalid = resolve_metadata_cue_source(
            crate::convert::pipeline::CueSidecarPolicy::PreferEmbedded,
            &surface,
            &invalid,
        )
        .expect_err("an invalid present embedded CUE must not fall back silently");
        assert!(prefer_invalid.contains("invalid under the selected CUE policy"));
    }

